$ErrorActionPreference = 'Stop'

# --- права администратора (нужны для WinDivert) ---
$principal = New-Object System.Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Start-Process powershell.exe -Verb RunAs -WindowStyle Hidden -ArgumentList "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -STA -File `"$PSCommandPath`""
    exit
}

Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase, System.Windows.Forms, System.Drawing
Add-Type -AssemblyName System.Net.Http

$script:AppDir = Split-Path -Parent $PSCommandPath
$script:SettingsPath = Join-Path $script:AppDir 'zapret-studio.json'

try {
    $created = $false
    $script:Mutex = New-Object System.Threading.Mutex($true, 'Global\ZapretStudioSingleton', [ref]$created)
    if (-not $created) { exit }

$script:IcoB64 = ''
$script:LogoB64 = ''

# ---------------------------------------------------------------- заставка при запуске
function Pump-Ui {
    $f = New-Object Windows.Threading.DispatcherFrame
    [void][Windows.Threading.Dispatcher]::CurrentDispatcher.BeginInvoke([Windows.Threading.DispatcherPriority]::Background, [Windows.Threading.DispatcherOperationCallback]{ param($o) $o.Continue = $false; $null }, $f)
    [Windows.Threading.Dispatcher]::PushFrame($f)
}
function Close-Splash {
    $sp = $script:Splash
    if (-not $sp) { return }
    $script:Splash = $null
    try {
        $a = New-Object Windows.Media.Animation.DoubleAnimation
        $a.From = 1.0; $a.To = 0.0; $a.Duration = New-Object Windows.Duration -ArgumentList ([TimeSpan]::FromMilliseconds(420))
        $a.Add_Completed({ try { $sp.Close() } catch { } }.GetNewClosure())
        $sp.BeginAnimation([Windows.UIElement]::OpacityProperty, $a)
    } catch { try { $sp.Close() } catch { } }
}
$script:Splash = $null
try {
    $acc = '#7C5CFF'; $fnt = ''
    try {
        if (Test-Path -LiteralPath $script:SettingsPath) {
            $j = Get-Content -LiteralPath $script:SettingsPath -Raw -Encoding UTF8 | ConvertFrom-Json
            if ([string]$j.Accent -match '^#[0-9A-Fa-f]{6}$') { $acc = [string]$j.Accent }
            if ($j.Font) { $fnt = [string]$j.Font }
        }
    } catch { }
    $splashXaml = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        WindowStyle="None" AllowsTransparency="True" Background="Transparent" ShowInTaskbar="False" Topmost="True"
        WindowStartupLocation="CenterScreen" ResizeMode="NoResize" Width="640" Height="340" Opacity="0"
        UseLayoutRounding="True" SnapsToDevicePixels="True" FontFamily="Segoe UI">
  <Grid Margin="26">
    <Border CornerRadius="26" BorderThickness="1" BorderBrush="#2EFFFFFF">
      <Border.Background>
        <LinearGradientBrush StartPoint="0,0" EndPoint="1,1">
          <GradientStop Color="#13131C" Offset="0"/>
          <GradientStop Color="#1D1736" Offset="1"/>
        </LinearGradientBrush>
      </Border.Background>
      <Border.Effect><DropShadowEffect BlurRadius="30" ShadowDepth="0" Opacity="0.65" Color="Black"/></Border.Effect>
      <Grid>
        <Border CornerRadius="26" Opacity="0.4">
          <Border.Background>
            <RadialGradientBrush Center="0.5,0" GradientOrigin="0.5,0" RadiusX="0.7" RadiusY="0.8">
              <GradientStop Color="__ACC__" Offset="0"/>
              <GradientStop Color="#00000000" Offset="1"/>
            </RadialGradientBrush>
          </Border.Background>
        </Border>
        <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center">
          <Image x:Name="SpLogo" Width="84" Height="84" Opacity="0" RenderTransformOrigin="0.5,0.5" RenderOptions.BitmapScalingMode="HighQuality">
            <Image.RenderTransform><ScaleTransform x:Name="SpLogoScale" ScaleX="0.6" ScaleY="0.6"/></Image.RenderTransform>
            <Image.Effect><DropShadowEffect BlurRadius="26" ShadowDepth="0" Opacity="0.8" Color="__ACC__"/></Image.Effect>
          </Image>
          <TextBlock x:Name="SpTitle" Text="Нет блокировкам в интернете!" FontSize="28" FontWeight="SemiBold" HorizontalAlignment="Center"
                     Margin="0,22,0,0" Opacity="0">
            <TextBlock.Foreground>
              <LinearGradientBrush StartPoint="0,0" EndPoint="1,0">
                <GradientStop Color="#FFFFFF" Offset="0"/>
                <GradientStop Color="#E6E1FF" Offset="0.6"/>
                <GradientStop Color="__ACC__" Offset="1"/>
              </LinearGradientBrush>
            </TextBlock.Foreground>
            <TextBlock.RenderTransform><TranslateTransform x:Name="SpTitleMove" Y="16"/></TextBlock.RenderTransform>
          </TextBlock>
          <TextBlock x:Name="SpSub" Text="Zapret Studio" FontSize="13" Foreground="#9AA0B8" HorizontalAlignment="Center" Margin="0,8,0,0" Opacity="0"/>
          <Border Width="230" Height="4" CornerRadius="2" Background="#1FFFFFFF" Margin="0,30,0,0" ClipToBounds="True">
            <Border x:Name="SpBar" Width="90" Height="4" CornerRadius="2" HorizontalAlignment="Left" Background="__ACC__">
              <Border.RenderTransform><TranslateTransform x:Name="SpBarMove" X="-90"/></Border.RenderTransform>
            </Border>
          </Border>
        </StackPanel>
        <TextBlock Text="dadramus  ©  2026" FontSize="10" Foreground="#5E6380" HorizontalAlignment="Center" VerticalAlignment="Bottom" Margin="0,0,0,14"/>
      </Grid>
    </Border>
  </Grid>
</Window>
'@
    $w = [Windows.Markup.XamlReader]::Parse($splashXaml.Replace('__ACC__', $acc))
    $bi = New-Object Windows.Media.Imaging.BitmapImage
    $bi.BeginInit(); $bi.StreamSource = New-Object IO.MemoryStream -ArgumentList (, [Convert]::FromBase64String($script:LogoB64)); $bi.CacheOption = 'OnLoad'; $bi.EndInit(); $bi.Freeze()
    $w.FindName('SpLogo').Source = $bi
    if ($fnt) { try { $w.FontFamily = New-Object Windows.Media.FontFamily($fnt) } catch { } }
    $w.Show()
    $script:Splash = $w
    $script:SplashT0 = Get-Date
    $ease = New-Object Windows.Media.Animation.CubicEase; $ease.EasingMode = 'EaseOut'
    $mk = {
        param([double]$from, [double]$to, [int]$ms, [int]$delay)
        $a = New-Object Windows.Media.Animation.DoubleAnimation
        $a.From = $from; $a.To = $to
        $a.Duration = New-Object Windows.Duration -ArgumentList ([TimeSpan]::FromMilliseconds($ms))
        $a.BeginTime = [TimeSpan]::FromMilliseconds($delay)
        $a.EasingFunction = $ease
        $a
    }
    $w.BeginAnimation([Windows.UIElement]::OpacityProperty, (& $mk 0 1 380 0))
    $w.FindName('SpLogo').BeginAnimation([Windows.UIElement]::OpacityProperty, (& $mk 0 1 500 120))
    $sc = $w.FindName('SpLogoScale')
    $sc.BeginAnimation([Windows.Media.ScaleTransform]::ScaleXProperty, (& $mk 0.6 1 650 120))
    $sc.BeginAnimation([Windows.Media.ScaleTransform]::ScaleYProperty, (& $mk 0.6 1 650 120))
    $w.FindName('SpTitle').BeginAnimation([Windows.UIElement]::OpacityProperty, (& $mk 0 1 600 380))
    $w.FindName('SpTitleMove').BeginAnimation([Windows.Media.TranslateTransform]::YProperty, (& $mk 16 0 650 380))
    $w.FindName('SpSub').BeginAnimation([Windows.UIElement]::OpacityProperty, (& $mk 0 1 600 800))
    $bar = New-Object Windows.Media.Animation.DoubleAnimation
    $bar.From = -90.0; $bar.To = 230.0; $bar.Duration = New-Object Windows.Duration -ArgumentList ([TimeSpan]::FromMilliseconds(1100))
    $bar.RepeatBehavior = [Windows.Media.Animation.RepeatBehavior]::Forever
    $w.FindName('SpBarMove').BeginAnimation([Windows.Media.TranslateTransform]::XProperty, $bar)
    Pump-Ui
} catch { $script:Splash = $null }

Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class ZNative {
    [StructLayout(LayoutKind.Sequential)] public struct AccentPolicy { public int AccentState; public int AccentFlags; public int GradientColor; public int AnimationId; }
    [StructLayout(LayoutKind.Sequential)] public struct WinCompAttrData { public int Attribute; public IntPtr Data; public int SizeOfData; }
    [DllImport("user32.dll")] static extern int SetWindowCompositionAttribute(IntPtr hwnd, ref WinCompAttrData data);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern IntPtr FindWindow(string cls, string title);
    [DllImport("user32.dll")] static extern bool ShowWindow(IntPtr h, int cmd);
    public static void Blur(IntPtr hwnd, bool on, byte a, byte r, byte g, byte b) {
        AccentPolicy ap = new AccentPolicy();
        ap.AccentState = on ? 4 : 0; ap.AccentFlags = 2;
        ap.GradientColor = unchecked((int)(((uint)a << 24) | ((uint)b << 16) | ((uint)g << 8) | (uint)r));
        int size = Marshal.SizeOf(ap);
        IntPtr p = Marshal.AllocHGlobal(size);
        Marshal.StructureToPtr(ap, p, false);
        WinCompAttrData d = new WinCompAttrData(); d.Attribute = 19; d.Data = p; d.SizeOfData = size;
        SetWindowCompositionAttribute(hwnd, ref d);
        Marshal.FreeHGlobal(p);
    }
    [DllImport("shell32.dll", CharSet = CharSet.Unicode)] static extern int SetCurrentProcessExplicitAppUserModelID(string id);
    [DllImport("user32.dll")] public static extern bool DestroyIcon(IntPtr h);
    [DllImport("user32.dll")] static extern bool ReleaseCapture();
    [DllImport("user32.dll")] static extern IntPtr SendMessage(IntPtr h, int msg, IntPtr w, IntPtr l);
    public static void SetAppId(string id) { try { SetCurrentProcessExplicitAppUserModelID(id); } catch (Exception) { } }
    public static void BeginResize(IntPtr hwnd, int dir) { ReleaseCapture(); SendMessage(hwnd, 0x112, (IntPtr)(0xF000 + dir), IntPtr.Zero); }
    [DllImport("kernel32.dll")] static extern uint SetThreadExecutionState(uint flags);
    public static void KeepAwake(bool on) {
        try { SetThreadExecutionState(on ? 0x80000001u : 0x80000000u); } catch (Exception) { }
    }
    public static bool HideWin(string title) {
        IntPtr h = FindWindow(null, title);
        if (h == IntPtr.Zero) return false;
        ShowWindow(h, 0);
        return true;
    }
}
'@

# свой AppUserModelID: в панели задач будет значок программы, а не PowerShell
[ZNative]::SetAppId('ZapretStudio.Launcher')

# ---------------------------------------------------------------- настройки
$Defaults = [ordered]@{
    Accent = '#7C5CFF'; Bg = '#12121A'; WindowOpacity = 0.96; PanelAlpha = 0.07; Radius = 18; Gradient = 0.18
    Glow = $true; Blur = $false; Topmost = $false
    TrayOnClose = $true; AutoStartLast = $false; StopOnExit = $false; HideConsole = $true
    StrategyDir = ''; Last = ''; Favorites = @(); Results = @{}
    Perf = $false; WinW = 1000; WinH = 690; PrioServices = @('yt', 'dc'); PrioMain = @(); PrioCustom = ''; Monitor = $true; MonitorMin = 3; AutoFix = $true; Aliases = @{}; Sort = 'name'
    Font = ''; FontScale = 100; TextColor = ''; Compact = $false; ShowDesc = $true
    KeepAlive = $true; TestMode = 'target'
}
$Cfg = @{}
foreach ($k in $Defaults.Keys) { $Cfg[$k] = $Defaults[$k] }
if (Test-Path -LiteralPath $script:SettingsPath) {
    try {
        $j = Get-Content -LiteralPath $script:SettingsPath -Raw -Encoding UTF8 | ConvertFrom-Json
        foreach ($p in $j.PSObject.Properties) { if ($Defaults.Contains($p.Name)) { $Cfg[$p.Name] = $p.Value } }
    } catch { }
}
$Cfg.FontScale = [Math]::Max(80, [Math]::Min(130, [int]$Cfg.FontScale))
$Cfg.Compact = [bool]$Cfg.Compact; $Cfg.ShowDesc = [bool]$Cfg.ShowDesc; $Cfg.KeepAlive = [bool]$Cfg.KeepAlive
if (@('target', 'full', 'urgent') -notcontains [string]$Cfg.TestMode) { $Cfg.TestMode = 'target' }
$Cfg.Favorites = @($Cfg.Favorites | Where-Object { $_ })
$Cfg.PrioServices = @($Cfg.PrioServices | Where-Object { $_ })
$Cfg.PrioMain = @($Cfg.PrioMain | Where-Object { $_ })
$Results = @{}
if ($Cfg.Results -is [System.Management.Automation.PSCustomObject]) {
    foreach ($p in $Cfg.Results.PSObject.Properties) { $Results[$p.Name] = [string]$p.Value }
}
$Aliases = @{}
if ($Cfg.Aliases -is [System.Management.Automation.PSCustomObject]) {
    foreach ($p in $Cfg.Aliases.PSObject.Properties) { $Aliases[$p.Name] = [string]$p.Value }
}
$script:SaveTimer = $null
function Save-Settings {
    try {
        if ($script:Ready -and $Win.WindowState -eq 'Normal' -and $Win.ActualWidth -gt 300) { $Cfg.WinW = [int]$Win.ActualWidth; $Cfg.WinH = [int]$Win.ActualHeight }
        $Cfg.Results = $Results; $Cfg.Aliases = $Aliases
        $Cfg | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $script:SettingsPath -Encoding UTF8
    } catch { }
}
function Request-Save { if ($script:SaveTimer) { $script:SaveTimer.Stop(); $script:SaveTimer.Start() } }

# ---------------------------------------------------------------- цвета
function ToColor([string]$hex) { try { [Windows.Media.ColorConverter]::ConvertFromString($hex) } catch { $null } }
function Lum($c) { (0.299 * $c.R + 0.587 * $c.G + 0.114 * $c.B) / 255 }
function Argb($c, [double]$a) {
    $v = [Math]::Max(0, [Math]::Min(255, [Math]::Round(255 * $a)))
    [Windows.Media.Color]::FromArgb([byte]$v, $c.R, $c.G, $c.B)
}
function Mix($c1, $c2, [double]$t) {
    [Windows.Media.Color]::FromRgb([byte]($c1.R + ($c2.R - $c1.R) * $t), [byte]($c1.G + ($c2.G - $c1.G) * $t), [byte]($c1.B + ($c2.B - $c1.B) * $t))
}
function New-Brush($c) { New-Object System.Windows.Media.SolidColorBrush $c }
function Hex($c) { '#{0:X2}{1:X2}{2:X2}' -f $c.R, $c.G, $c.B }
function GStop($c, [double]$o) { $g = New-Object System.Windows.Media.GradientStop; $g.Color = $c; $g.Offset = $o; $g }
