  <Style TargetType="ScrollBar">
    <Setter Property="Width" Value="8"/>
    <Setter Property="Background" Value="Transparent"/>
    <Setter Property="Template"><Setter.Value><ControlTemplate TargetType="ScrollBar">
      <Grid Background="Transparent">
        <Track x:Name="PART_Track" IsDirectionReversed="True">
          <Track.DecreaseRepeatButton><RepeatButton Command="ScrollBar.PageUpCommand"><RepeatButton.Template><ControlTemplate TargetType="RepeatButton"><Border Background="Transparent"/></ControlTemplate></RepeatButton.Template></RepeatButton></Track.DecreaseRepeatButton>
          <Track.IncreaseRepeatButton><RepeatButton Command="ScrollBar.PageDownCommand"><RepeatButton.Template><ControlTemplate TargetType="RepeatButton"><Border Background="Transparent"/></ControlTemplate></RepeatButton.Template></RepeatButton></Track.IncreaseRepeatButton>
          <Track.Thumb><Thumb><Thumb.Template><ControlTemplate TargetType="Thumb"><Border CornerRadius="4" Background="{DynamicResource TrackOffBrush}" Margin="1"/></ControlTemplate></Thumb.Template></Thumb></Track.Thumb>
        </Track>
      </Grid>
    </ControlTemplate></Setter.Value></Setter>
  </Style>
</Window.Resources>

<Grid>
<Border x:Name="ShadowHost" Margin="18" CornerRadius="18" Background="#12121A" IsHitTestVisible="False">
  <Border.Effect><DropShadowEffect BlurRadius="24" ShadowDepth="0" Opacity="0.4" Color="Black"/></Border.Effect>
</Border>
<Border x:Name="Shell" Margin="18" CornerRadius="18" BorderThickness="1" BorderBrush="{DynamicResource StrokeBrush}" Background="#F012121A">
  <Grid>
    <Grid.RowDefinitions><RowDefinition Height="52"/><RowDefinition Height="*"/></Grid.RowDefinitions>

    <Grid x:Name="TitleBar" Background="Transparent">
      <StackPanel Orientation="Horizontal" Margin="20,0,0,0" VerticalAlignment="Center">
        <Border x:Name="TitleLogoHost" Width="28" Height="28" CornerRadius="9" Background="{DynamicResource AccentBrush}">
          <TextBlock Text="Z" FontWeight="Black" FontSize="16" Foreground="{DynamicResource OnAccentBrush}" HorizontalAlignment="Center" VerticalAlignment="Center"/>
        </Border>
        <TextBlock Text="Zapret Studio" FontWeight="Bold" FontSize="15" Margin="12,0,0,0" VerticalAlignment="Center"/>
        <Button x:Name="BtnAbout" Style="{StaticResource LinkBtn}" FontSize="12" Content="О создателях" Margin="10,1,0,0" VerticalAlignment="Center" ToolTip="Автор, авторские права и лицензия"/>
      </StackPanel>
      <StackPanel Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,0,12,0" VerticalAlignment="Center">
        <Button x:Name="BtnPin" Style="{StaticResource TitleBtn}" Content="&#xE718;" ToolTip="Поверх всех окон"/>
        <Button x:Name="BtnMin" Style="{StaticResource TitleBtn}" Content="&#xE921;" ToolTip="Свернуть"/>
        <Button x:Name="BtnClose" Style="{StaticResource TitleClose}" Content="&#xE8BB;" ToolTip="Закрыть"/>
      </StackPanel>
    </Grid>

    <Grid Grid.Row="1" Margin="20,0,20,20">
      <Grid.ColumnDefinitions><ColumnDefinition Width="310"/><ColumnDefinition Width="18"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>

      <!-- LEFT: strategies -->
      <Grid>
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
        <DockPanel Margin="4,0,4,10">
          <TextBlock x:Name="CountText" DockPanel.Dock="Right" Foreground="{DynamicResource SubBrush}" VerticalAlignment="Center"/>
          <Button x:Name="BtnSort" DockPanel.Dock="Right" Style="{StaticResource Ghost}" Padding="9,3" FontSize="11" Margin="0,0,10,0" ToolTip="Порядок списка" Content="А–Я"/>
          <TextBlock Text="Стратегии" FontSize="17" FontWeight="Bold"/>
        </DockPanel>
        <Grid Grid.Row="1" Margin="0,0,0,10">
          <TextBox x:Name="SearchBox" Style="{StaticResource Input}"/>
          <TextBlock x:Name="SearchHint" Text="Поиск стратегии…" Foreground="{DynamicResource SubBrush}" IsHitTestVisible="False" Margin="14,0,0,0" VerticalAlignment="Center"/>
        </Grid>
        <ScrollViewer Grid.Row="2" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
          <StackPanel x:Name="ListHost" Margin="0,0,6,0"/>
        </ScrollViewer>
        <StackPanel Grid.Row="3" Margin="0,10,0,0">
          <Button x:Name="BtnAuto" Style="{StaticResource Ghost}" Content="Подбор под мои задачи"/>
          <Grid x:Name="ProgTrack" Height="4" Margin="2,10,2,0" Visibility="Collapsed">
            <Border CornerRadius="2" Background="{DynamicResource TrackOffBrush}"/>
            <Border x:Name="ProgFill" CornerRadius="2" Background="{DynamicResource AccentBrush}" HorizontalAlignment="Left" Width="0"/>
          </Grid>
          <TextBlock x:Name="AutoText" FontSize="11" Foreground="{DynamicResource SubBrush}" Margin="4,6,4,0" TextWrapping="Wrap"/>
        </StackPanel>
      </Grid>

      <!-- RIGHT -->
      <Grid Grid.Column="2">
        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="16"/><RowDefinition Height="Auto"/><RowDefinition Height="10"/><RowDefinition Height="*"/></Grid.RowDefinitions>

        <Border Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="18" Padding="24">
          <Grid>
            <Grid.ColumnDefinitions><ColumnDefinition Width="176"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
            <Grid Width="150" Height="150" HorizontalAlignment="Left">
              <Ellipse x:Name="RingPulse" Width="108" Height="108" Stroke="{DynamicResource AccentBrush}" StrokeThickness="2" Opacity="0" RenderTransformOrigin="0.5,0.5">
                <Ellipse.RenderTransform><ScaleTransform ScaleX="1" ScaleY="1"/></Ellipse.RenderTransform>
              </Ellipse>
              <Ellipse x:Name="OrbCore" Width="108" Height="108"/>
              <TextBlock x:Name="OrbGlyph" Text="&#xE7E8;" FontFamily="Segoe MDL2 Assets" FontSize="42" HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Grid>
            <StackPanel Grid.Column="1" VerticalAlignment="Center">
              <TextBlock x:Name="StatusText" FontSize="27" FontWeight="Bold" Text="Обход выключен"/>
              <TextBlock x:Name="StrategyText" Margin="0,4,0,0" Foreground="{DynamicResource SubBrush}" TextTrimming="CharacterEllipsis"/>
              <TextBlock x:Name="UptimeText" Margin="0,2,0,0" Foreground="{DynamicResource SubBrush}"/>
              <TextBlock x:Name="MonText" Margin="0,2,0,0" FontSize="11" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap"/>
              <Border x:Name="AlertBox" Visibility="Collapsed" Margin="0,10,0,0" Padding="12,8" CornerRadius="10" BorderThickness="1" BorderBrush="{DynamicResource DangerBrush}" Background="#26EF4444">
                <TextBlock x:Name="AlertText" FontSize="12" TextWrapping="Wrap"/>
              </Border>
              <StackPanel Orientation="Horizontal" Margin="0,20,0,0">
                <Button x:Name="BtnToggle" Style="{StaticResource Primary}" Width="210" Height="48" FontSize="15" FontWeight="SemiBold" Content="Запустить"/>
                <Button x:Name="BtnRestart" Style="{StaticResource Ghost}" Margin="10,0,0,0" Width="48" Height="48" Padding="0" FontFamily="Segoe MDL2 Assets" FontSize="16" Content="&#xE72C;" ToolTip="Перезапустить"/>
              </StackPanel>
            </StackPanel>
          </Grid>
        </Border>

        <Border Grid.Row="2" Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="13" Padding="4" HorizontalAlignment="Left">
          <WrapPanel Orientation="Horizontal">
            <RadioButton x:Name="TabLog" Style="{StaticResource Seg}" Padding="13,7" Content="Журнал" IsChecked="True" GroupName="tabs"/>
            <RadioButton x:Name="TabLook" Style="{StaticResource Seg}" Padding="13,7" Content="Оформление" GroupName="tabs"/>
            <RadioButton x:Name="TabFont" Style="{StaticResource Seg}" Padding="13,7" Content="Шрифт" GroupName="tabs"/>
            <RadioButton x:Name="TabSet" Style="{StaticResource Seg}" Padding="13,7" Content="Настройки" GroupName="tabs"/>
            <RadioButton x:Name="TabHelp" Style="{StaticResource Seg}" Padding="13,7" Content="Инструкция" GroupName="tabs"/>
          </WrapPanel>
        </Border>

        <Grid Grid.Row="4">
          <Border x:Name="PageLog" Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="16" Padding="14,12,8,10">
            <Grid>
              <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
              <DockPanel Margin="0,0,6,10">
                <StackPanel DockPanel.Dock="Right" Orientation="Horizontal">
                  <Button x:Name="BtnLogCopy" Style="{StaticResource Ghost}" Padding="11,5" FontSize="12" Content="Копировать"/>
                  <Button x:Name="BtnLogClear" Style="{StaticResource Ghost}" Padding="11,5" FontSize="12" Margin="6,0,0,0" Content="Очистить"/>
                </StackPanel>
                <StackPanel Orientation="Horizontal">
                  <RadioButton x:Name="FltAll" Style="{StaticResource Seg}" Padding="12,5" FontSize="12" Content="Все" IsChecked="True" GroupName="logf"/>
                  <RadioButton x:Name="FltKey" Style="{StaticResource Seg}" Padding="12,5" FontSize="12" Content="Важное" GroupName="logf"/>
                  <RadioButton x:Name="FltBad" Style="{StaticResource Seg}" Padding="12,5" FontSize="12" Content="Проблемы" GroupName="logf"/>
                </StackPanel>
              </DockPanel>
              <ScrollViewer x:Name="LogScroll" Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                <Grid>
                  <StackPanel x:Name="LogHost" Margin="0,0,6,0"/>
                  <TextBlock x:Name="LogEmpty" Text="Здесь появятся события: запуск, проверки и сбои" Foreground="{DynamicResource SubBrush}" HorizontalAlignment="Center" Margin="0,40,0,0"/>
                </Grid>
              </ScrollViewer>
            </Grid>
          </Border>

          <Border x:Name="PageLook" Visibility="Collapsed" Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="16" Padding="18,14,10,14">
            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
              <StackPanel Margin="0,0,12,0">
                <TextBlock Text="ЦВЕТ АКЦЕНТА" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,0,0,8"/>
                <WrapPanel x:Name="AccentDots"/>
                <SliderRow Name="SlR" Title="Красный" Min="0" Max="255"/>
                <SliderRow Name="SlG" Title="Зелёный" Min="0" Max="255"/>
                <SliderRow Name="SlB" Title="Синий" Min="0" Max="255"/>
                <Grid Margin="0,0,0,18">
                  <Grid.ColumnDefinitions><ColumnDefinition Width="190"/><ColumnDefinition Width="110"/></Grid.ColumnDefinitions>
                  <TextBlock Text="Свой цвет (HEX)" VerticalAlignment="Center"/>
                  <TextBox x:Name="HexAccent" Grid.Column="1" Style="{StaticResource Input}" Padding="10,6" MaxLength="7"/>
                </Grid>
                <TextBlock Text="ФОН" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,0,0,8"/>
                <WrapPanel x:Name="BgDots"/>
                <Grid Margin="0,0,0,18">
                  <Grid.ColumnDefinitions><ColumnDefinition Width="190"/><ColumnDefinition Width="110"/></Grid.ColumnDefinitions>
                  <TextBlock Text="Свой фон (HEX)" VerticalAlignment="Center"/>
                  <TextBox x:Name="HexBg" Grid.Column="1" Style="{StaticResource Input}" Padding="10,6" MaxLength="7"/>
                </Grid>
                <TextBlock Text="СТЕКЛО И ФОРМА" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,0,0,10"/>
                <SliderRow Name="SlOpacity" Title="Прозрачность окна" Min="30" Max="100"/>
                <SliderRow Name="SlPanel" Title="Прозрачность панелей" Min="2" Max="30"/>
                <SliderRow Name="SlGrad" Title="Градиент акцента" Min="0" Max="45"/>
                <SliderRow Name="SlRadius" Title="Скругление углов" Min="0" Max="32"/>
                <Toggle Name="ChkGlow" Title="Свечение" Sub="Мягкое свечение шара при активном обходе"/>
                <Toggle Name="ChkBlur" Title="Размытие фона (Acrylic)" Sub="Экспериментально: окно станет прямоугольным"/>
                <Button x:Name="BtnResetLook" Style="{StaticResource Ghost}" Content="Сбросить оформление" HorizontalAlignment="Left" Margin="0,4,0,6"/>
              </StackPanel>
            </ScrollViewer>
          </Border>

          <Border x:Name="PageFont" Visibility="Collapsed" Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="16" Padding="18,14,10,14">
            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
              <StackPanel Margin="0,0,12,0">
                <TextBlock Text="ШРИФТ" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,0,0,8"/>
                <WrapPanel x:Name="FontChips" Margin="0,0,0,4"/>
                <TextBlock Text="Нет блокировкам в интернете!" FontSize="15" Margin="0,4,0,12"/>
                <Grid Margin="0,0,0,18">
                  <Grid.ColumnDefinitions><ColumnDefinition Width="190"/><ColumnDefinition Width="200"/></Grid.ColumnDefinitions>
                  <TextBlock Text="Другой шрифт (название)" VerticalAlignment="Center"/>
                  <TextBox x:Name="FontBox" Grid.Column="1" Style="{StaticResource Input}" Padding="10,6"/>
                </Grid>
                <TextBlock Text="РАЗМЕР" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,0,0,10"/>
                <SliderRow Name="SlFont" Title="Размер текста" Min="80" Max="130"/>
                <TextBlock Text="ЦВЕТ ТЕКСТА" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,8,0,8"/>
                <WrapPanel x:Name="TextDots"/>
                <Grid Margin="0,0,0,18">
                  <Grid.ColumnDefinitions><ColumnDefinition Width="190"/><ColumnDefinition Width="110"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                  <TextBlock Text="Свой цвет (HEX)" VerticalAlignment="Center"/>
                  <TextBox x:Name="HexText" Grid.Column="1" Style="{StaticResource Input}" Padding="10,6" MaxLength="7"/>
                  <Button x:Name="BtnTextAuto" Grid.Column="2" Style="{StaticResource Ghost}" Padding="12,6" Margin="8,0,0,0" Content="Авто"/>
                </Grid>
                <TextBlock Text="СПИСОК СТРАТЕГИЙ" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,0,0,10"/>
                <Toggle Name="ChkCompact" Title="Компактный список" Sub="Карточки ниже и плотнее"/>
                <Toggle Name="ChkDesc" Title="Описания под названиями" Sub="Короткая строка о том, для чего стратегия"/>
                <Button x:Name="BtnResetFont" Style="{StaticResource Ghost}" Content="Сбросить шрифт" HorizontalAlignment="Left" Margin="0,4,0,6"/>
              </StackPanel>
            </ScrollViewer>
          </Border>

          <Border x:Name="PageSet" Visibility="Collapsed" Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="16" Padding="18,14,10,14">
            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
              <StackPanel Margin="0,0,12,0">
                <StackPanel Margin="0,0,0,12"><TextBlock Text="ОКНО И ЗАПУСК" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <Toggle Name="ChkTray" Title="Сворачивать в трей при закрытии" Sub="Крестик прячет окно, обход продолжает работать"/>
                <Toggle Name="ChkAutoLast" Title="Запускать последнюю стратегию при старте" Sub="Автоматически поднимать обход при запуске программы"/>
                <Toggle Name="ChkWinStart" Title="Запускать вместе с Windows" Sub="Через планировщик задач, с правами администратора"/>
                <Toggle Name="ChkTop" Title="Поверх всех окон" Sub=""/>
                <Toggle Name="ChkStopExit" Title="Останавливать обход при выходе" Sub="Полный выход через меню в трее"/>
                <StackPanel Margin="0,18,0,12"><TextBlock Text="ОБХОД (WINWS)" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <Toggle Name="ChkHide" Title="Прятать окно winws" Sub="Консоль zapret не будет висеть на панели задач"/>
                <Toggle Name="ChkKeep" Title="Не давать обходу обрываться" Sub="Перезапуск, если winws закрылся сам, после сна компьютера, смены сети или сбоя связи. Не сдаётся: повторяет попытки со сбросом WinDivert"/>
                <StackPanel Margin="0,18,0,12"><TextBlock Text="СЛЕЖЕНИЕ ЗА СВЯЗЬЮ" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <Toggle Name="ChkMon" Title="Следить за связью" Sub="Раз в несколько минут проверяет ваши сервисы из подбора. При сбое значок краснеет и пишет причину"/>
                <SliderRow Name="SlMonInt" Title="Интервал проверки" Min="1" Max="5"/>
                <Toggle Name="ChkAutoFix" Title="Автовосстановление" Sub="При сбое: перезапуск стратегии, затем следующая лучшая из подбора"/>
                <Button x:Name="BtnCheckNow" Style="{StaticResource Ghost}" Content="Проверить связь сейчас" HorizontalAlignment="Left" Margin="0,0,0,14"/>
                <StackPanel Margin="0,18,0,12"><TextBlock Text="ПРОИЗВОДИТЕЛЬНОСТЬ" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <Toggle Name="ChkPerf" Title="Режим производительности" Sub="Без теней, свечения и анимаций. Включите, если интерфейс тормозит"/>
                <StackPanel Margin="0,18,0,12"><TextBlock Text="ПАПКА СО СТРАТЕГИЯМИ" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <TextBlock x:Name="FolderText" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap" Margin="0,0,0,10"/>
                <StackPanel Orientation="Horizontal" Margin="0,0,0,6">
                  <Button x:Name="BtnFolder" Style="{StaticResource Ghost}" Content="Выбрать папку…"/>
                  <Button x:Name="BtnRescan" Style="{StaticResource Ghost}" Content="Обновить список" Margin="8,0,0,0"/>
                  <Button x:Name="BtnOpen" Style="{StaticResource Ghost}" Content="Открыть" Margin="8,0,0,0"/>
                </StackPanel>
                <StackPanel Margin="0,18,0,12"><TextBlock Text="ЯРЛЫК" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource AccentBrush}"/><Border Height="1" Background="{DynamicResource StrokeBrush}" Margin="0,6,0,0"/></StackPanel>
                <TextBlock Text="Ярлык со значком перечёркнутого РКН: запускайте программу с рабочего стола" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap" Margin="0,0,0,10"/>
                <Button x:Name="BtnShortcut" Style="{StaticResource Ghost}" Content="Создать ярлык на рабочем столе" HorizontalAlignment="Left" Margin="0,0,0,6"/>
              </StackPanel>
            </ScrollViewer>
          </Border>

          <Border x:Name="PageHelp" Visibility="Collapsed" Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="16" Padding="18,14,10,14">
            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
              <StackPanel x:Name="HelpHost" Margin="0,0,12,0"/>
            </ScrollViewer>
          </Border>
        </Grid>
      </Grid>
    </Grid>
    <Border x:Name="Overlay" Grid.RowSpan="2" Visibility="Collapsed" Background="#B3000000" CornerRadius="18">
      <Grid>
        <Border x:Name="PrioPanel" Visibility="Collapsed" Width="480" MaxHeight="580" Margin="20" HorizontalAlignment="Center" VerticalAlignment="Center" Background="{DynamicResource DialogBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="18" Padding="24,22">
          <DockPanel>
            <TextBlock DockPanel.Dock="Top" Text="Что для вас важнее?" FontSize="20" FontWeight="Bold"/>
            <TextBlock DockPanel.Dock="Top" Margin="0,6,0,14" TextWrapping="Wrap" Foreground="{DynamicResource SubBrush}" Text="Отметьте сервисы: стратегии проверят именно на них. Звёздочка делает сервис главным, и его вес в 2 раза больше."/>
            <StackPanel DockPanel.Dock="Bottom" Margin="0,14,0,0">
              <TextBlock x:Name="PrioEta" FontSize="11" Foreground="{DynamicResource SubBrush}" Margin="0,0,0,10"/>
              <StackPanel Orientation="Horizontal" HorizontalAlignment="Right">
                <Button x:Name="BtnPrioCancel" Style="{StaticResource Ghost}" Content="Отмена"/>
                <Button x:Name="BtnPrioStart" Style="{StaticResource Primary}" Margin="10,0,0,0" Content="Начать проверку"/>
              </StackPanel>
            </StackPanel>
            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
              <StackPanel Margin="0,0,6,0">
                <TextBlock Text="РЕЖИМ ПРОВЕРКИ" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,0,0,6"/>
                <Border Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="13" Padding="4" HorizontalAlignment="Left">
                  <WrapPanel Orientation="Horizontal">
                    <RadioButton x:Name="ModeTarget" Style="{StaticResource Seg}" Padding="12,6" Content="Только нужная" GroupName="pmode" IsChecked="True" ToolTip="Проверяет все стратегии, но только на отмеченных сервисах, и показывает рейтинг. Сама ничего не подключает."/>
                    <RadioButton x:Name="ModeFull" Style="{StaticResource Seg}" Padding="12,6" Content="Полная проверка" GroupName="pmode" ToolTip="Проверяет все стратегии на все сервисы из списка (отметки не нужны). Самый долгий режим, зато самая полная картина."/>
                    <RadioButton x:Name="ModeUrgent" Style="{StaticResource Seg}" Padding="12,6" Content="Срочная проверка" GroupName="pmode" ToolTip="Ищет стратегию для отмеченных сервисов и сразу подключает первую, которая открывает их все. Дальше не проверяет."/>
                  </WrapPanel>
                </Border>
                <TextBlock x:Name="ModeDesc" FontSize="11" Foreground="{DynamicResource SubBrush}" TextWrapping="Wrap" Margin="2,8,0,14"/>
                <TextBlock Text="СЕРВИСЫ" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,0,0,6"/>
                <StackPanel x:Name="PrioList"/>
                <TextBlock Text="СВОЙ САЙТ (НЕОБЯЗАТЕЛЬНО)" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource SubBrush}" Margin="0,10,0,6"/>
                <TextBox x:Name="PrioCustom" Style="{StaticResource Input}" ToolTip="Например: example.com, other.org"/>
              </StackPanel>
            </ScrollViewer>
          </DockPanel>
        </Border>
        <Border x:Name="AboutPanel" Visibility="Collapsed" Width="540" MaxHeight="560" Margin="20" HorizontalAlignment="Center" VerticalAlignment="Center" Background="{DynamicResource DialogBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" CornerRadius="18" Padding="24,22">
          <DockPanel>
            <TextBlock DockPanel.Dock="Top" Text="О создателях" FontSize="20" FontWeight="Bold"/>
            <StackPanel DockPanel.Dock="Bottom" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,14,0,0">
              <Button x:Name="BtnAboutClose" Style="{StaticResource Primary}" Content="Закрыть"/>
            </StackPanel>
            <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Margin="0,12,0,0">
              <StackPanel Margin="0,0,8,0">
                <Border CornerRadius="12" Background="{DynamicResource PanelBrush}" BorderBrush="{DynamicResource StrokeBrush}" BorderThickness="1" Padding="16,12" Margin="0,0,0,6">
                  <StackPanel>
                    <TextBlock Text="Zapret Studio" FontSize="17" FontWeight="Bold"/>
                    <TextBlock Text="Автор и правообладатель: dadramus" FontWeight="SemiBold" Margin="0,6,0,0"/>
                    <TextBlock Text="Помощь в создании: KolRau" FontWeight="SemiBold" Margin="0,2,0,0"/>
                    <TextBlock Text="© 2026 dadramus. Все права защищены." Foreground="{DynamicResource SubBrush}" Margin="0,2,0,0"/>
                  </StackPanel>
                </Border>

