})

# размеры шрифта идут через ресурсы Fs11, Fs12 ... - их масштабирует вкладка "Шрифт"
$script:FsUsed = @{}
function Scale-Xaml([string]$x) {
    $r = [regex]::Replace($x, '<[A-Za-z][^<>]*>', {
        param($m)
        $t = $m.Value
        if ($t -match 'MDL2|Symbol|Consolas') { return $t }
        [regex]::Replace($t, '\bFontSize="(\d+)"', { param($k) 'FontSize="{DynamicResource Fs' + $k.Groups[1].Value + '}"' })
    })
    foreach ($mm in [regex]::Matches($r, 'Fs(\d+)\}')) { $script:FsUsed[[int]$mm.Groups[1].Value] = 1 }
    if ($app) { Set-FsRes }
    $r
}
function Set-FsRes {
    $k = [double]$Cfg.FontScale / 100
    foreach ($i in @($script:FsUsed.Keys)) { $app.Resources['Fs' + $i] = [double][Math]::Round([int]$i * $k, 1) }
}
$Xaml = Scale-Xaml $Xaml
$app = New-Object System.Windows.Application
$app.ShutdownMode = 'OnExplicitShutdown'
Set-FsRes
Pump-Ui
$Win = [Windows.Markup.XamlReader]::Parse($Xaml)
function N([string]$n) { $Win.FindName($n) }
foreach ($n in 'RenamePanel','RenameBox','RenFile','RenChip','BtnRenReset','BtnRenCancel','BtnRenSave','BtnSort','AlertBox','AlertText','MonText','ChkMon','ChkAutoFix','SlMonInt','LbSlMonInt','BtnCheckNow','Shell','ShadowHost','Overlay','PrioPanel','ResultPanel','PrioList','PrioCustom','PrioEta','BtnPrioCancel','BtnPrioStart','ResTitle','ResBest','ResBestSub','ResList','BtnResClose','BtnResRun','TitleLogoHost','ChkPerf','BtnShortcut','GripL','GripR','GripT','GripB','GripTL','GripTR','GripBL','GripBR','TitleBar','BtnPin','BtnMin','BtnClose','CountText','SearchBox','SearchHint','ListHost','BtnAuto','ProgTrack','ProgFill','AutoText',
    'RingPulse','OrbCore','OrbGlyph','StatusText','StrategyText','UptimeText','BtnToggle','BtnRestart','TabLog','TabLook','TabSet','PageLog','PageLook','PageSet','LogHost','LogScroll','LogEmpty','FltAll','FltKey','FltBad','BtnLogClear','BtnLogCopy',
    'AccentDots','BgDots','SlR','SlG','SlB','HexAccent','HexBg','SlOpacity','SlPanel','SlGrad','SlRadius','ChkGlow','ChkBlur','BtnResetLook',
    'ChkTray','ChkAutoLast','ChkStopExit','ChkHide','ChkTop','ChkWinStart','FolderText','BtnFolder','BtnRescan','BtnOpen',
    'LbSlR','LbSlG','LbSlB','LbSlOpacity','LbSlPanel','LbSlGrad','LbSlRadius','TabFont','PageFont','FontChips','FontBox','SlFont','LbSlFont','TextDots','HexText','BtnTextAuto','ChkCompact','ChkDesc','BtnResetFont','TabHelp','PageHelp','HelpHost','BtnAbout','AboutPanel','BtnAboutClose','ChkKeep','ModeTarget','ModeFull','ModeUrgent','ModeDesc') {
