$script:SaveTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:SaveTimer.Interval = [TimeSpan]::FromMilliseconds(700)
$script:SaveTimer.Add_Tick({ $script:SaveTimer.Stop(); Save-Settings })

$script:LogItems = New-Object System.Collections.ArrayList
$script:LogFilter = 'all'
$logRowXaml = @'
<Border xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" CornerRadius="9" Padding="8,6" Margin="0,0,0,3" Background="__BG__">
  <Grid>
    <Grid.ColumnDefinitions><ColumnDefinition Width="62"/><ColumnDefinition Width="30"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
    <TextBlock x:Name="Tm" FontFamily="Consolas" FontSize="11" Foreground="{DynamicResource SubBrush}" VerticalAlignment="Center"/>
    <Grid x:Name="Badge" Grid.Column="1" Width="20" Height="20" HorizontalAlignment="Left">
      <Ellipse Fill="{DynamicResource __BR__}" Opacity="0.22"/>
      <TextBlock x:Name="Gl" FontFamily="Segoe UI Symbol" FontSize="11" FontWeight="Bold" Foreground="{DynamicResource __BR__}" HorizontalAlignment="Center" VerticalAlignment="Center"/>
    </Grid>
    <TextBlock x:Name="Msg" Grid.Column="2" TextWrapping="Wrap" VerticalAlignment="Center" LineHeight="18"/>
  </Grid>
</Border>
'@
$logRowXaml = Scale-Xaml $logRowXaml

function Get-LogLevel([string]$m) {
    if ($m -match '^\s') { return 'detail' }
    if ($m -match '^(.+?): (\d+)%') {
        $p = [int]$Matches[2]
        if ($p -ge 80) { return 'ok' } elseif ($p -ge 40) { return 'warn' } else { return 'err' }
    }
    if ($m -match 'ПРОБЛЕМА|Ошибка|слишком часто|не удалось|не создан|winws не запустился|не помогло') { return 'err' }
    if ($m -match 'не запустилась|вылетела|оборвался|перепроверю|Нет стратегий|проверять нечего|Идёт подбор|нет интернета') { return 'warn' }
    if ($m -match 'Обход активен|восстановлена|Ярлык создан|Автозапуск с Windows: включён|^Лучшая:|^Подключено:|готов\.|досрочно') { return 'ok' }
    if ($m -match 'Запуск стратегии|^Подбор:|Автовосстановление|^Тест ') { return 'step' }
    return 'info'
}

function Apply-LogFilter {
    foreach ($it in $script:LogItems) {
        $show = switch ($script:LogFilter) {
            'key' { $it.Level -ne 'info' }
            'bad' { $it.Level -in 'warn', 'err' }
            default { $true }
        }
        if ($show) { $it.El.Visibility = 'Visible' } else { $it.El.Visibility = 'Collapsed' }
    }
    $LogEmpty.Visibility = if ($script:LogItems.Count -eq 0) { 'Visible' } else { 'Collapsed' }
}

function Log([string]$m, [string]$Level = '') {
    $detail = $m -match '^\s'
    if (-not $Level) { $Level = Get-LogLevel $m }
    $eff = $Level
    if ($Level -eq 'detail') { $eff = 'info'; if ($script:LogItems.Count -gt 0) { $eff = $script:LogItems[$script:LogItems.Count - 1].Level } }
    $br = 'SubBrush'; $glyph = [string][char]0x25CF; $bg = 'Transparent'
    switch ($eff) {
        'ok'   { $br = 'OkBrush'; $glyph = [string][char]0x2713 }
        'warn' { $br = 'WarnBrush'; $glyph = '!'; $bg = '#14F59E0B' }
        'err'  { $br = 'DangerBrush'; $glyph = [string][char]0x2715; $bg = '#1AEF4444' }
        'step' { $br = 'AccentBrush'; $glyph = [string][char]0x25B6 }
    }
    $row = [Windows.Markup.XamlReader]::Parse($logRowXaml.Replace('__BR__', $br).Replace('__BG__', $bg))
    $msg = $row.FindName('Msg'); $tm = $row.FindName('Tm'); $badge = $row.FindName('Badge')
    $now = Get-Date
    if ($detail) {
        $row.Padding = New-Object System.Windows.Thickness 8, 0, 8, 3
        $badge.Visibility = 'Hidden'; $tm.Text = ''
        $msg.Text = $m.Trim()
        $msg.Foreground = $Win.Resources['SubBrush']; $msg.FontSize = 12
        $indent = ([regex]::Match($m, '^\s*')).Length
        if ($indent -gt 3) { $msg.Margin = New-Object System.Windows.Thickness 14, 0, 0, 0 }
    } else {
        $tm.Text = $now.ToString('HH:mm:ss')
        $row.FindName('Gl').Text = $glyph
        if ($m -match '^(.+?): (\d+%.*)$') {
            $r1 = New-Object System.Windows.Documents.Run ($Matches[1])
            $r1.FontWeight = 'SemiBold'
            $r2 = New-Object System.Windows.Documents.Run (': ' + $Matches[2])
            $r2.Foreground = $Win.Resources['SubBrush']
            [void]$msg.Inlines.Add($r1); [void]$msg.Inlines.Add($r2)
        } else {
            $msg.Text = $m
            if ($eff -eq 'err' -or $eff -eq 'warn') { $msg.FontWeight = 'SemiBold' }
        }
    }
    $stick = $LogScroll.VerticalOffset -ge ($LogScroll.ScrollableHeight - 40)
    [void]$LogHost.Children.Add($row)
    [void]$script:LogItems.Add(@{ El = $row; Level = $eff; Text = ('[{0:HH:mm:ss}] {1}' -f $now, $m.TrimEnd()) })
    while ($script:LogItems.Count -gt 300) { $LogHost.Children.RemoveAt(0); $script:LogItems.RemoveAt(0) }
    if ($script:LogFilter -ne 'all') {
        $last = $script:LogItems[$script:LogItems.Count - 1]
        $ok = ($script:LogFilter -eq 'key' -and $eff -ne 'info') -or ($script:LogFilter -eq 'bad' -and ($eff -eq 'warn' -or $eff -eq 'err'))
        if (-not $ok) { $row.Visibility = 'Collapsed' }
    }
    $LogEmpty.Visibility = 'Collapsed'
    if ($stick) { $LogScroll.UpdateLayout(); $LogScroll.ScrollToEnd() }
}

