$script:Ready = $false
$script:Running = $false; $script:Starting = $false; $script:Testing = $false
$script:Active = $null; $script:Selected = $null; $script:StartedAt = $null
$script:Cards = @{}; $script:Strategies = @(); $script:WorkDir = $script:AppDir
$script:HideUntil = $null; $script:HideTitle = $null

$script:B = @{}
$script:LastGeo = ''; $script:LastBlur = $null
$script:ShellGrad = $null; $script:OrbOn = $null; $script:ShadowBrush = $null

function Set-Res([string]$key, $value) {
    if ($value -is [System.Management.Automation.PSObject]) { $value = $value.psobject.BaseObject }
    $Win.Resources[$key] = $value
}

# Кисти темы создаются один раз, потом меняется только их цвет - это в разы дешевле, чем пересоздавать ресурсы.
function Set-BrushColor([string]$key, $c) {
    $b = $script:B[$key]
    if (-not $b) { $nb = New-Brush $c; $script:B[$key] = $nb; Set-Res $key $nb; return }
    try { $b.Color = $c } catch { $nb = New-Brush $c; $script:B[$key] = $nb; Set-Res $key $nb }
}

function Apply-Blur {
    $h = (New-Object System.Windows.Interop.WindowInteropHelper $Win).Handle
    if ($h -eq [IntPtr]::Zero) { return }
    try { [ZNative]::Blur($h, [bool]$Cfg.Blur, 1, 0, 0, 0) } catch { }
}

function Set-Grips([bool]$blur) {
    if ($blur) { $t = 6; $c = 12 } else { $t = 18; $c = 24 }
    $GripL.Width = $t; $GripR.Width = $t; $GripT.Height = $t; $GripB.Height = $t
    $m1 = New-Object System.Windows.Thickness 0, $c, 0, $c
    $m2 = New-Object System.Windows.Thickness $c, 0, $c, 0
    $GripL.Margin = $m1; $GripR.Margin = $m1; $GripT.Margin = $m2; $GripB.Margin = $m2
    foreach ($g in $GripTL, $GripTR, $GripBL, $GripBR) { $g.Width = $c; $g.Height = $c }
}

function Apply-Theme([switch]$Full) {
    $acc = ToColor $Cfg.Accent; if (-not $acc) { $acc = ToColor '#7C5CFF' }
    $bg = ToColor $Cfg.Bg; if (-not $bg) { $bg = ToColor '#12121A' }
    $light = (Lum $bg) -gt 0.62
    if ($light) { $fg = ToColor '#151821'; $ov = ToColor '#000000' } else { $fg = ToColor '#F3F4FA'; $ov = ToColor '#FFFFFF' }
    if ($Cfg.TextColor) { $tcol = ToColor $Cfg.TextColor; if ($tcol) { $fg = $tcol } }
    $pa = [double]$Cfg.PanelAlpha
    $wa = [double]$Cfg.WindowOpacity

    Set-Res 'AccentColor' $acc
    Set-BrushColor 'AccentBrush' $acc
    if ((Lum $acc) -gt 0.72) { Set-BrushColor 'OnAccentBrush' (ToColor '#111318') } else { Set-BrushColor 'OnAccentBrush' (ToColor '#FFFFFF') }
    Set-BrushColor 'TextBrush' $fg
    Set-BrushColor 'SubBrush' (Argb $fg 0.62)
    Set-BrushColor 'PanelBrush' (Argb $ov $pa)
    Set-BrushColor 'HoverBrush' (Argb $ov ([Math]::Min(0.5, $pa * 1.9 + 0.03)))
    Set-BrushColor 'StrokeBrush' (Argb $ov 0.12)
    Set-BrushColor 'TrackOffBrush' (Argb $ov 0.26)
    Set-BrushColor 'DialogBrush' (Argb $bg 0.985)

    # фон окна: градиент создаётся один раз
    if (-not $script:ShellGrad) {
        $lg = New-Object System.Windows.Media.LinearGradientBrush
        $lg.StartPoint = New-Object System.Windows.Point 0, 0
        $lg.EndPoint = New-Object System.Windows.Point 1, 1
        $script:ShellS0 = GStop $bg 0; $script:ShellS1 = GStop $bg 1
        $lg.GradientStops.Add($script:ShellS0); $lg.GradientStops.Add($script:ShellS1)
        $Shell.Background = $lg
        $script:ShellGrad = $lg
        $script:ShadowBrush = New-Brush $bg
        $ShadowHost.Background = $script:ShadowBrush
    }
    $script:ShellS0.Color = Argb $bg $wa
    $script:ShellS1.Color = Argb (Mix $bg $acc ([double]$Cfg.Gradient)) $wa
    $script:ShadowBrush.Color = $bg

    # форма окна, тень, зоны изменения размера - только когда что-то реально поменялось
    $shadowOn = (-not $Cfg.Perf) -and (-not $Cfg.Blur) -and ($wa -ge 0.9)
    $geo = '{0}|{1}|{2}' -f [bool]$Cfg.Blur, [int]$Cfg.Radius, $shadowOn
    if ($geo -ne $script:LastGeo) {
        $script:LastGeo = $geo
        if ($Cfg.Blur) {
            $Shell.CornerRadius = New-Object System.Windows.CornerRadius 0
            $Shell.Margin = New-Object System.Windows.Thickness 0
        } else {
            $Shell.CornerRadius = New-Object System.Windows.CornerRadius ([double]$Cfg.Radius)
            $Shell.Margin = New-Object System.Windows.Thickness 18
        }
        $ShadowHost.CornerRadius = $Shell.CornerRadius
        $ShadowHost.Margin = $Shell.Margin
        $Overlay.CornerRadius = $Shell.CornerRadius
        if ($shadowOn) { $ShadowHost.Visibility = 'Visible' } else { $ShadowHost.Visibility = 'Collapsed' }
        Set-Grips ([bool]$Cfg.Blur)
    }

    # шар и свечение - объекты создаются один раз
    if (-not $script:OrbOn) {
        $orb = New-Object System.Windows.Media.RadialGradientBrush
        $orb.GradientOrigin = New-Object System.Windows.Point 0.35, 0.3
        $orb.Center = New-Object System.Windows.Point 0.5, 0.5
        $script:OrbS0 = GStop $acc 0; $script:OrbS1 = GStop $acc 0.75; $script:OrbS2 = GStop $acc 1
        $orb.GradientStops.Add($script:OrbS0); $orb.GradientStops.Add($script:OrbS1); $orb.GradientStops.Add($script:OrbS2)
        $script:OrbOn = $orb
        $script:OrbOff = New-Brush $acc
        $fx = New-Object System.Windows.Media.Effects.DropShadowEffect
        $fx.BlurRadius = 40; $fx.ShadowDepth = 0; $fx.Opacity = 0.85
        $script:OrbFx = $fx
    }
    $script:OrbS0.Color = Mix $acc ([Windows.Media.Colors]::White) 0.35
    $script:OrbS1.Color = $acc
    $script:OrbS2.Color = Mix $acc ([Windows.Media.Colors]::Black) 0.25
    $script:OrbOff.Color = Argb $ov ([Math]::Min(0.4, $pa * 1.6 + 0.04))
    $script:OrbFx.Color = $acc
    $script:AccColor = $acc

    if ($script:LastBlur -ne [bool]$Cfg.Blur) {
        $script:LastBlur = [bool]$Cfg.Blur
        if ($script:Ready) { Apply-Blur }
    }
    if ($Full -and $script:Ready) { Render-State }
}

# лёгкая версия: вызывается не чаще ~30 раз в секунду, пока двигаете ползунки
$script:ThemeTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:ThemeTimer.Interval = [TimeSpan]::FromMilliseconds(33)
$script:ThemeTimer.Add_Tick({ $script:ThemeTimer.Stop(); Apply-Theme })
function Queue-Theme { if (-not $script:ThemeTimer.IsEnabled) { $script:ThemeTimer.Start() } }

# ---------------------------------------------------------------- иконка
function Load-Branding {
    try {
        $script:IcoBytes = [Convert]::FromBase64String($script:IcoB64)
        $script:LogoBytes = [Convert]::FromBase64String($script:LogoB64)
    } catch { $script:IcoBytes = $null; $script:LogoBytes = $null }
}

function Set-WindowIcons {
    if ($script:IcoBytes) {
        try {
            $ms = [System.IO.MemoryStream]::new($script:IcoBytes)
            $dec = [System.Windows.Media.Imaging.IconBitmapDecoder]::new($ms, [System.Windows.Media.Imaging.BitmapCreateOptions]::None, [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad)
            $script:WinIconNormal = $dec.Frames[0]
            $Win.Icon = $script:WinIconNormal
        } catch { }
    }
    if ($script:LogoBytes) {
        try {
            $ms2 = [System.IO.MemoryStream]::new($script:LogoBytes)
            $bi = New-Object System.Windows.Media.Imaging.BitmapImage
            $bi.BeginInit(); $bi.StreamSource = $ms2; $bi.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad; $bi.EndInit(); $bi.Freeze()
            $img = New-Object System.Windows.Controls.Image
            $img.Source = $bi; $img.Stretch = 'Uniform'
            [System.Windows.Media.RenderOptions]::SetBitmapScalingMode($img, [System.Windows.Media.BitmapScalingMode]::HighQuality)
            $TitleLogoHost.Background = $null
            $TitleLogoHost.Child = $img
        } catch { }
    }
}

function Ensure-IconFile {
    $p = Join-Path $script:AppDir 'ZapretStudio.ico'
    if ($script:IcoBytes -and -not (Test-Path -LiteralPath $p)) { try { [System.IO.File]::WriteAllBytes($p, $script:IcoBytes) } catch { } }
    $p
}

function Get-LaunchCmd {
    $vbs = Join-Path $script:AppDir 'ZapretStudio.vbs'
    if (Test-Path -LiteralPath $vbs) {
        return @{ File = (Join-Path $env:WINDIR 'System32\wscript.exe'); Args = ('//nologo "' + $vbs + '"'); Short = 'wscript.exe' }
    }
    return @{ File = (Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'); Args = ('-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -STA -File "' + $PSCommandPath + '"'); Short = 'powershell.exe' }
}
function New-AppShortcut {
    try {
        $ico = Ensure-IconFile
        $path = Join-Path ([Environment]::GetFolderPath('Desktop')) 'Zapret Studio.lnk'
        $ws = New-Object -ComObject WScript.Shell
        $l = $ws.CreateShortcut($path)
        $lc = Get-LaunchCmd
        $l.TargetPath = $lc.File
        $l.Arguments = $lc.Args
        $l.WorkingDirectory = $script:AppDir
        $l.IconLocation = $ico + ',0'
        $l.WindowStyle = 7
        $l.Description = 'Zapret Studio'
        $l.Save()
        Log ('Ярлык создан на рабочем столе: ' + $path)
    } catch { Log ('Ярлык не создан: ' + $_.Exception.Message) }
}

$script:TrayKey = $null; $script:WinIconNormal = $null; $script:WinAlertKey = $false
function Update-TrayIcon {
    if (-not $script:Tray -or -not $script:LogoBytes) { return }
    $alert = [bool]$script:Alert
    $key = '{0}|{1}' -f [bool]$script:Running, $alert
    if ($script:TrayKey -eq $key) { return }
    $script:TrayKey = $key
    try {
        $bmp = New-Object System.Drawing.Bitmap 32, 32
        $g = [System.Drawing.Graphics]::FromImage($bmp)
        $g.SmoothingMode = 'AntiAlias'; $g.InterpolationMode = 'HighQualityBicubic'; $g.TextRenderingHint = 'AntiAliasGridFit'
        if ($alert) {
            $rb = New-Object System.Drawing.SolidBrush ([System.Drawing.Color]::FromArgb(255, 226, 37, 45))
            $wp = New-Object System.Drawing.Pen ([System.Drawing.Color]::White), 2
            $g.FillEllipse($rb, 1, 1, 30, 30); $g.DrawEllipse($wp, 2, 2, 28, 28)
            $f = New-Object System.Drawing.Font 'Segoe UI', 24, ([System.Drawing.FontStyle]::Bold), ([System.Drawing.GraphicsUnit]::Pixel)
            $sf = New-Object System.Drawing.StringFormat; $sf.Alignment = 'Center'; $sf.LineAlignment = 'Center'
            $g.DrawString('!', $f, [System.Drawing.Brushes]::White, (New-Object System.Drawing.RectangleF 0, 1, 32, 32), $sf)
            $rb.Dispose(); $wp.Dispose(); $f.Dispose()
        } else {
            $src = [System.Drawing.Bitmap]::new([System.IO.MemoryStream]::new($script:LogoBytes))
            $g.DrawImage($src, 0, 0, 32, 32)
            $src.Dispose()
            if ($script:Running) {
                $w = New-Object System.Drawing.SolidBrush ([System.Drawing.Color]::FromArgb(255, 255, 255, 255))
                $gr = New-Object System.Drawing.SolidBrush ([System.Drawing.Color]::FromArgb(255, 34, 197, 94))
                $g.FillEllipse($w, 17, 17, 15, 15); $g.FillEllipse($gr, 19, 19, 11, 11)
                $w.Dispose(); $gr.Dispose()
            }
        }
        $g.Dispose()
        $h = $bmp.GetHicon()
        # значок окна / панели задач тоже краснеет
        if ($alert -ne $script:WinAlertKey) {
            $script:WinAlertKey = $alert
            try {
                if ($alert) {
                    $bs = [System.Windows.Interop.Imaging]::CreateBitmapSourceFromHIcon($h, [System.Windows.Int32Rect]::Empty, [System.Windows.Media.Imaging.BitmapSizeOptions]::FromEmptyOptions())
                    $bs.Freeze(); $Win.Icon = $bs
                } elseif ($script:WinIconNormal) { $Win.Icon = $script:WinIconNormal }
            } catch { }
        }
        $tmp = [System.Drawing.Icon]::FromHandle($h)
        $new = $tmp.Clone()
        [void][ZNative]::DestroyIcon($h)
        $old = $script:Tray.Icon
        $script:Tray.Icon = $new
        if ($old) { try { $old.Dispose() } catch { } }
        $bmp.Dispose()
    } catch { }
}

# ---------------------------------------------------------------- стратегии
function Sort-Key([string]$n) { [regex]::Replace($n.ToLower(), '\d+', { param($m) $m.Value.PadLeft(6, '0') }) }

function Find-Strategies {
    $dir = $Cfg.StrategyDir
    if (-not $dir -or -not (Test-Path -LiteralPath $dir)) { $dir = $script:AppDir }
    $skip = '^(service|cloudflare|switch|check|update|remove|uninstall|install|test)'
    $files = @(Get-ChildItem -LiteralPath $dir -Filter *.bat -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -notmatch $skip })
    if ($files.Count -eq 0) {
        $g = Get-ChildItem -LiteralPath $dir -Recurse -Depth 2 -Filter 'general*.bat' -File -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($g) {
            $dir = $g.DirectoryName
            $files = @(Get-ChildItem -LiteralPath $dir -Filter *.bat -File | Where-Object { $_.Name -notmatch $skip })
        }
    }
    $script:WorkDir = $dir
    $script:Strategies = @($files | ForEach-Object { [pscustomobject]@{ Name = $_.BaseName; Path = $_.FullName } })
    $FolderText.Text = $dir
}

$cardXaml = @'
<Border xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Style="{DynamicResource CardStyle}">
  <Grid>
    <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
    <Border x:Name="Bar" Width="3" CornerRadius="2" Margin="0,2,10,2" Background="{DynamicResource AccentBrush}" Visibility="Hidden"/>
    <StackPanel Grid.Column="1" VerticalAlignment="Center">
      <TextBlock x:Name="Title" FontWeight="SemiBold" TextTrimming="CharacterEllipsis"/>
      <TextBlock x:Name="Sub" FontSize="11" Foreground="{DynamicResource SubBrush}" Margin="0,2,0,0" TextTrimming="CharacterEllipsis"/>
    </StackPanel>
    <TextBlock x:Name="Sub2" Grid.Column="2" FontSize="11" Foreground="{DynamicResource SubBrush}" Margin="8,0,0,0" MaxWidth="150" TextTrimming="CharacterEllipsis" VerticalAlignment="Center" Visibility="Collapsed"/>
    <TextBlock x:Name="Star" Grid.Column="3" FontFamily="Segoe UI Symbol" FontSize="18" VerticalAlignment="Center" Cursor="Hand" Padding="8,0,0,0"/>
  </Grid>
</Border>
'@
$cardXaml = Scale-Xaml $cardXaml

function Card-Refresh($name) {
    $card = $script:Cards[$name]; if (-not $card) { return }
    $bar = $card.FindName('Bar'); $sub = $card.FindName('Sub'); $sub2 = $card.FindName('Sub2'); $star = $card.FindName('Star')
    $parts = @()
    if ($script:BestName -eq $name) { $parts += 'лучшая' }
    if ($Results.ContainsKey($name)) { $parts += ([string]$Results[$name] -replace '\s{2,}', ' ') }
    $sub.Text = (Get-SInfo $name).Desc
    if ($Cfg.ShowDesc) { $sub.Visibility = 'Visible' } else { $sub.Visibility = 'Collapsed' }
    if ($Cfg.Compact) { $card.Padding = New-Object System.Windows.Thickness 12, 6, 12, 6; $card.Margin = New-Object System.Windows.Thickness 0, 0, 0, 4 }
    else { $card.Padding = New-Object System.Windows.Thickness 12, 10, 12, 10; $card.Margin = New-Object System.Windows.Thickness 0, 0, 0, 6 }
    $sub2.Text = ($parts -join ' · ')
    if ($parts.Count -gt 0) { $sub2.Visibility = 'Visible' } else { $sub2.Visibility = 'Collapsed' }
    if ($script:Running -and $script:Active -eq $name) { $bar.Visibility = 'Visible' } else { $bar.Visibility = 'Hidden' }
    if ($Cfg.Favorites -contains $name) { $star.Text = [string][char]0x2605; $star.Foreground = New-Brush (ToColor '#FFC83D') }
    else { $star.Text = [string][char]0x2606; $star.Foreground = $Win.Resources['SubBrush'] }
    if ($script:Selected -eq $name) { $card.SetResourceReference([Windows.Controls.Border]::BorderBrushProperty, 'AccentBrush') }
    else { $card.BorderBrush = [Windows.Media.Brushes]::Transparent }
}
$script:BestName = $null
function Cards-Refresh {
    $script:BestName = $null
    $b = Get-RankedNames | Select-Object -First 1
    if ($b -and (Get-Pct $b) -gt 0) { $script:BestName = $b }
    foreach ($n in @($script:Cards.Keys)) { Card-Refresh $n }
}

function Select-Strategy($name) { $script:Selected = $name; Cards-Refresh; Render-State }

function Toggle-Fav($name) {
    $f = @($Cfg.Favorites)
    if ($f -contains $name) { $f = @($f | Where-Object { $_ -ne $name }) } else { $f += $name }
    $Cfg.Favorites = $f
    Request-Save; Rebuild-List
}

# красивая подсказка-карточка: полное название, описание, результат теста, файл
function Update-CardTip($card) {
    $name = [string]$card.Tag; if (-not $name -or -not $card.ToolTip) { return }
    $i = Get-SInfo $name
    $fam = $Win.FontFamily
    $fs = 13.0; try { $fs = [double]$app.Resources['Fs13'] } catch { }
    $mk = {
        param([string]$text, [double]$size, $brush, [bool]$bold)
        $t = New-Object System.Windows.Controls.TextBlock
        $t.Text = $text; $t.TextWrapping = 'Wrap'; $t.FontFamily = $fam; $t.FontSize = $size; $t.Foreground = $brush
        if ($bold) { $t.FontWeight = 'Bold' }
        $t
    }
    $txt = $Win.Resources['TextBrush']; $sub = $Win.Resources['SubBrush']
    $sp = New-Object System.Windows.Controls.StackPanel
    $sp.MaxWidth = 340
    $head = New-Object System.Windows.Controls.TextBlock
    $head.TextWrapping = 'Wrap'; $head.FontFamily = $fam; $head.FontSize = $fs + 4; $head.FontWeight = 'Bold'; $head.Foreground = $txt
    $dot = New-Object System.Windows.Documents.Run ([string][char]0x25CF + ' ')
    $dot.Foreground = New-Brush (ToColor $i.Color); $dot.FontSize = $fs
    [void]$head.Inlines.Add($dot); [void]$head.Inlines.Add((New-Object System.Windows.Documents.Run (Get-Title $name)))
    [void]$sp.Children.Add($head)
    if ($i.Chip) { $c = & $mk $i.Chip ($fs) $sub $false; $c.Margin = New-Object System.Windows.Thickness 0, 2, 0, 0; [void]$sp.Children.Add($c) }
    if ($i.Desc) { $d = & $mk $i.Desc $fs $txt $false; $d.Margin = New-Object System.Windows.Thickness 0, 10, 0, 0; [void]$sp.Children.Add($d) }
    $lines = @()
    if ($script:BestName -eq $name) { $lines += 'лучшая по тесту' }
    if ($Results.ContainsKey($name)) { $lines += ('результат: ' + ([string]$Results[$name] -replace '\s{2,}', ' ')) }
    if ($lines.Count -gt 0) {
        $r = & $mk ($lines -join "`n") ($fs - 1) $sub $false; $r.Margin = New-Object System.Windows.Thickness 0, 10, 0, 0
        [void]$sp.Children.Add($r)
    }
    $fl = & $mk ($name + '.bat') ($fs - 2) $sub $false
    $fl.FontFamily = New-Object System.Windows.Media.FontFamily 'Consolas'; $fl.Margin = New-Object System.Windows.Thickness 0, 12, 0, 0; $fl.Opacity = 0.75
    [void]$sp.Children.Add($fl)
    $h = & $mk 'Двойной щелчок — запустить' ($fs - 2) $sub $false; $h.Opacity = 0.6; $h.Margin = New-Object System.Windows.Thickness 0, 4, 0, 0
    [void]$sp.Children.Add($h)
    $b = New-Object System.Windows.Controls.Border
    $b.Background = $Win.Resources['DialogBrush']; $b.BorderBrush = $Win.Resources['StrokeBrush']
    $b.BorderThickness = New-Object System.Windows.Thickness 1; $b.CornerRadius = New-Object System.Windows.CornerRadius 12
    $b.Padding = New-Object System.Windows.Thickness 16, 13, 16, 13; $b.Child = $sp
    $card.ToolTip.Content = $b
}

function Rebuild-List {
    $ListHost.Children.Clear(); $script:Cards = @{}
    $q = $SearchBox.Text.Trim()
    $items = @($script:Strategies | Where-Object { Match-Strat $_.Name $q } |
        Sort-Object @{ Expression = { if ($Cfg.Favorites -contains $_.Name) { 0 } else { 1 } } }, @{ Expression = { if ($Cfg.Sort -eq 'score') { -(Get-Pct $_.Name) } else { 0 } } }, @{ Expression = { Sort-Key $_.Name } })
    $CountText.Text = "{0} шт." -f $script:Strategies.Count
    foreach ($st in $items) {
        $card = [Windows.Markup.XamlReader]::Parse($cardXaml)
        Set-CardTitle $card.FindName('Title') $st.Name
        $card.Tag = $st.Name
        $tt = New-Object System.Windows.Controls.ToolTip
        $tt.Background = [Windows.Media.Brushes]::Transparent; $tt.BorderThickness = New-Object System.Windows.Thickness 0
        $tt.Padding = New-Object System.Windows.Thickness 0; $tt.HasDropShadow = $false
        $tt.Placement = 'Right'; $tt.HorizontalOffset = 10; $tt.Content = ' '
        $card.ToolTip = $tt
        [Windows.Controls.ToolTipService]::SetInitialShowDelay($card, 350)
        [Windows.Controls.ToolTipService]::SetShowDuration($card, 30000)
        $card.Add_ToolTipOpening({ param($sender, $ev) Update-CardTip $sender })
        $card.Add_MouseRightButtonUp({ param($sender, $ev) $ev.Handled = $true; Select-Strategy ([string]$sender.Tag); Show-CardMenu ([string]$sender.Tag) $sender })
        $star = $card.FindName('Star'); $star.Tag = $st.Name
        $star.Add_MouseLeftButtonDown({ param($sender, $ev) $ev.Handled = $true })
        $star.Add_MouseLeftButtonUp({ param($sender, $ev) $ev.Handled = $true; Toggle-Fav $sender.Tag })
        $card.Add_MouseLeftButtonDown({ param($sender, $ev)
            if ($ev.ClickCount -ge 2) { Select-Strategy $sender.Tag; Start-Strategy $sender.Tag } else { Select-Strategy $sender.Tag } })
        $script:Cards[$st.Name] = $card
        [void]$ListHost.Children.Add($card)
        Card-Refresh $st.Name
    }
}

# ---------------------------------------------------------------- названия стратегий
# Номера и буквы в скобках всегда остаются как в имени файла: (ALT3), (FAKE TLS AUTO ALT2) и т.д.
$script:InfoCache = @{}
$script:KindTable = @{
    main   = @('Классика', '#F59E0B', 'Основная · подходит большинству')
    alt    = @('Запасной план', '#60A5FA', 'Если основная не помогла')
    tls    = @('Умный TLS', '#A78BFA', 'Автоподмена TLS-рукопожатия')
    simple = @('Лёгкий режим', '#E879F9', 'Простая подмена, мягкий режим')
    mgts   = @('МГТС-профиль', '#F97316', 'Для провайдера МГТС')
}
function Get-SInfo([string]$name) {
    if ($script:InfoCache.ContainsKey($name)) { return $script:InfoCache[$name] }
    $chip = ''; $base = $name; $inner = ''
    $m = [regex]::Match($name, '^(.*?)\s*\(([^)]*)\)\s*$')
    if ($m.Success) { $base = $m.Groups[1].Value; $inner = $m.Groups[2].Value; $chip = '(' + $inner + ')' }
    $u = (($base + ' ' + $inner).ToUpper()) -replace '[_\-]+', ' '
    $kind = 'other'
    if ($u -match 'FAKE' -and $u -match 'TLS' -and $u -match 'AUTO') { $kind = 'tls' }
    elseif ($u -match 'SIMPLE') { $kind = 'simple' }
    elseif ($u -match 'МГТС|MGTS') { $kind = 'mgts' }
    elseif ($u -match '\bALT\d*\b') { $kind = 'alt' }
    elseif ($base -match '^general$') { $kind = 'main' }
    if (-not $chip -and $kind -ne 'main' -and $kind -ne 'other') {
        $rest = ($name -replace '^general[\s_\-]*', '').Trim()
        if ($rest) { $chip = '(' + $rest + ')' }
    }
    if ($kind -eq 'other') { $title = $base; $color = '#94A3B8'; $desc = '' }
    else { $k = $script:KindTable[$kind]; $title = $k[0]; $color = $k[1]; $desc = $k[2] }
    $info = [pscustomobject]@{ Title = $title; Chip = $chip; Kind = $kind; Color = $color; Desc = $desc }
    $script:InfoCache[$name] = $info
    $info
}

function Get-Title([string]$name) {
    if ($Aliases.ContainsKey($name) -and $Aliases[$name]) { return $Aliases[$name] }
    (Get-SInfo $name).Title
}
function Disp([string]$name) {
    if (-not $name) { return '' }
    $i = Get-SInfo $name
    $t = Get-Title $name
    if ($i.Chip) { return ($t + ' ' + $i.Chip) }
    $t
}

function Set-CardTitle($tb, [string]$name) {
    $i = Get-SInfo $name
    $tb.Inlines.Clear()
    $dot = New-Object System.Windows.Documents.Run ([string][char]0x25CF + ' ')
    $dot.Foreground = New-Brush (ToColor $i.Color); $dot.FontSize = 10
    $r = New-Object System.Windows.Documents.Run (Get-Title $name)
    [void]$tb.Inlines.Add($dot); [void]$tb.Inlines.Add($r)
    if ($i.Chip) {
        $c = New-Object System.Windows.Documents.Run ('  ' + $i.Chip)
        $c.Foreground = $Win.Resources['SubBrush']; $c.FontWeight = 'Normal'; $c.FontSize = 12
        [void]$tb.Inlines.Add($c)
    }
}

function Get-Pct([string]$name) {
    if ($Results.ContainsKey($name) -and $Results[$name] -match '^(\d+)%') { return [int]$Matches[1] }
    -1
}
function Match-Strat([string]$name, [string]$q) {
    if (-not $q) { return $true }
    $i = Get-SInfo $name
    $hay = (Disp $name) + ' ' + $name + ' ' + $i.Desc
    $hay.IndexOf($q, [StringComparison]::OrdinalIgnoreCase) -ge 0
}

# ---------- контекстное меню карточки и переименование
function New-MI([string]$header, [string]$tag, [scriptblock]$sb) {
    $mi = New-Object System.Windows.Controls.MenuItem
    $mi.Header = $header; $mi.Tag = $tag; $mi.Style = $Win.Resources['CtxItem']
    $mi.Add_Click($sb)
    $mi
}
function Show-CardMenu([string]$name, $target) {
    $menu = New-Object System.Windows.Controls.ContextMenu
    $menu.Style = $Win.Resources['Ctx']
    if (@($Cfg.Favorites) -contains $name) { $fav = 'Убрать из избранного' } else { $fav = 'В избранное' }
    [void]$menu.Items.Add((New-MI 'Запустить' $name { param($s, $e) Select-Strategy ([string]$s.Tag); Start-Strategy ([string]$s.Tag) }))
    [void]$menu.Items.Add((New-MI $fav $name { param($s, $e) Toggle-Fav ([string]$s.Tag) }))
    [void]$menu.Items.Add((New-MI 'Переименовать…' $name { param($s, $e) Show-Rename ([string]$s.Tag) }))
    [void]$menu.Items.Add((New-MI 'Открыть .bat в блокноте' $name { param($s, $e)
        $st = $script:Strategies | Where-Object { $_.Name -eq [string]$s.Tag } | Select-Object -First 1
        if ($st) { Start-Process notepad.exe -ArgumentList ('"' + $st.Path + '"') } }))
    [void]$menu.Items.Add((New-MI 'Показать в папке' $name { param($s, $e)
        $st = $script:Strategies | Where-Object { $_.Name -eq [string]$s.Tag } | Select-Object -First 1
        if ($st) { Start-Process explorer.exe -ArgumentList ('/select,"' + $st.Path + '"') } }))
    $menu.PlacementTarget = $target
    $menu.IsOpen = $true
}

$script:RenName = $null
function Show-Rename([string]$name) {
    $script:RenName = $name
    $i = Get-SInfo $name
    $RenFile.Text = 'Файл: ' + $name + '.bat'
    $RenameBox.Text = Get-Title $name
    if ($i.Chip) { $RenChip.Text = 'Номер в скобках останется как есть: ' + $i.Chip } else { $RenChip.Text = '' }
    $PrioPanel.Visibility = 'Collapsed'; $ResultPanel.Visibility = 'Collapsed'; $RenamePanel.Visibility = 'Visible'; $Overlay.Visibility = 'Visible'
    [void]$RenameBox.Focus(); $RenameBox.SelectAll()
}
function Save-Rename([bool]$reset) {
    $n = $script:RenName
    if ($n) {
        $t = $RenameBox.Text.Trim()
        if ($reset -or -not $t -or $t -eq (Get-SInfo $n).Title) { [void]$Aliases.Remove($n) } else { $Aliases[$n] = $t }
        Request-Save
    }
    Hide-Overlay
    Rebuild-List; Render-State
}

# ---------------------------------------------------------------- запуск / остановка
function Stop-Zapret([switch]$Full) {
    Get-Process -Name winws -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
    if ($Full) {
        foreach ($svc in 'WinDivert', 'WinDivert14') {
            try { Start-Process sc.exe -ArgumentList "stop $svc" -WindowStyle Hidden -Wait } catch { }
        }
    }
    $script:Running = $false; $script:Starting = $false; $script:Active = $null; $script:StartedAt = $null
}

function Start-Strategy([string]$name, [switch]$Auto) {
    $st = $script:Strategies | Where-Object { $_.Name -eq $name } | Select-Object -First 1
    if (-not $st) { return }
    if (-not $Auto) { Clear-Alert }
    Stop-Zapret
    Log ('Запуск стратегии: ' + (Disp $name))
    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = $env:ComSpec
    $psi.Arguments = '/c ""' + $st.Path + '""'
    $psi.WorkingDirectory = $script:WorkDir
    $psi.UseShellExecute = $false
    $psi.CreateNoWindow = $true
    try { [void][Diagnostics.Process]::Start($psi) } catch { Log ('Ошибка запуска: ' + $_.Exception.Message); Render-State; return }
    $script:Active = $name; $script:Starting = $true
    $script:StartDeadline = (Get-Date).AddSeconds(8)
    $script:HideTitle = "zapret: $name"; $script:HideUntil = (Get-Date).AddSeconds(15)
    $script:LastStrategy = $name
    $script:NextCheck = (Get-Date).AddSeconds(15); if (-not $Auto) { $script:MonConfirm = $false }
    if (-not $script:Testing) { $Cfg.Last = $name; Request-Save; $script:KeepArmed = $true }
    Cards-Refresh; Render-State
}

function Stop-ByUser {
    if ($script:Testing) { Stop-Test }
    Clear-Alert; $script:NextCheck = $null
    $script:KeepArmed = $false; $script:KeepRetryAt = $null; $script:RestartAt = $null
    Stop-Zapret -Full
    Log 'Обход остановлен'
    Cards-Refresh; Render-State
}

# ---------------------------------------------------------------- состояние
$script:PulseOn = $false; $script:WantPulse = $false
function Set-Pulse([bool]$on) {
    $script:WantPulse = $on
    $eff = $on -and (-not $Cfg.Perf) -and $Win.IsVisible -and ($Win.WindowState -ne 'Minimized')
    if ($eff -eq $script:PulseOn) { return }
    $script:PulseOn = $eff
    $st = $RingPulse.RenderTransform
    if ($eff) {
        $d = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(1.9))
        $a = New-Object System.Windows.Media.Animation.DoubleAnimation; $a.From = 0.95; $a.To = 1.45; $a.Duration = $d
        $a.RepeatBehavior = [Windows.Media.Animation.RepeatBehavior]::Forever
        $o = New-Object System.Windows.Media.Animation.DoubleAnimation; $o.From = 0.75; $o.To = 0; $o.Duration = $d
        $o.RepeatBehavior = [Windows.Media.Animation.RepeatBehavior]::Forever
        try {
            $a.SetValue([Windows.Media.Animation.Timeline]::DesiredFrameRateProperty, [Nullable[int]]30)
            $o.SetValue([Windows.Media.Animation.Timeline]::DesiredFrameRateProperty, [Nullable[int]]30)
        } catch { }
        $st.BeginAnimation([Windows.Media.ScaleTransform]::ScaleXProperty, $a)
        $st.BeginAnimation([Windows.Media.ScaleTransform]::ScaleYProperty, $a)
        $RingPulse.BeginAnimation([Windows.UIElement]::OpacityProperty, $o)
    } else {
        $st.BeginAnimation([Windows.Media.ScaleTransform]::ScaleXProperty, $null)
        $st.BeginAnimation([Windows.Media.ScaleTransform]::ScaleYProperty, $null)
        $RingPulse.BeginAnimation([Windows.UIElement]::OpacityProperty, $null)
        $RingPulse.Opacity = 0
    }
}

function Render-State {
    if ($script:Testing) {
        $StatusText.Text = 'Идёт подбор…'; $StatusText.Foreground = $Win.Resources['WarnBrush']
        $StrategyText.Text = $AutoText.Text; $BtnToggle.Content = 'Остановить тест'
        $BtnToggle.SetResourceReference([Windows.Controls.Button]::BackgroundProperty, 'DangerBrush')
        $OrbCore.Fill = $script:OrbOn; $OrbGlyph.Foreground = [Windows.Media.Brushes]::White; Set-Pulse $true
        $BtnToggle.IsEnabled = $true; return
    }
    if ($script:Running) {
        $StatusText.Text = 'Обход активен'; $StatusText.Foreground = $Win.Resources['OkBrush']
        if ($script:Active) { $StrategyText.Text = 'Стратегия: ' + (Disp $script:Active) } else { $StrategyText.Text = 'Запущено вне приложения' }
        $BtnToggle.Content = 'Остановить'
        $BtnToggle.SetResourceReference([Windows.Controls.Button]::BackgroundProperty, 'DangerBrush')
        $OrbCore.Fill = $script:OrbOn; $OrbGlyph.Foreground = [Windows.Media.Brushes]::White; Set-Pulse $true
        if ($Cfg.Glow -and -not $Cfg.Perf) { $OrbCore.Effect = $script:OrbFx } else { $OrbCore.Effect = $null }
        $BtnToggle.IsEnabled = $true
    } elseif ($script:Starting) {
        $StatusText.Text = 'Запуск…'; $StatusText.Foreground = $Win.Resources['WarnBrush']
        $StrategyText.Text = 'Стратегия: ' + (Disp $script:Active); $BtnToggle.Content = 'Остановить'
        $BtnToggle.SetResourceReference([Windows.Controls.Button]::BackgroundProperty, 'DangerBrush')
        $OrbCore.Fill = $script:OrbOn; $OrbGlyph.Foreground = [Windows.Media.Brushes]::White; Set-Pulse $false; $OrbCore.Effect = $null
        $BtnToggle.IsEnabled = $true
    } else {
        $StatusText.Text = 'Обход выключен'; $StatusText.Foreground = $Win.Resources['TextBrush']
        if ($script:Selected) { $StrategyText.Text = 'Выбрано: ' + (Disp $script:Selected) } else { $StrategyText.Text = 'Выберите стратегию слева' }
        $UptimeText.Text = ''
        $BtnToggle.Content = 'Запустить'
        $BtnToggle.SetResourceReference([Windows.Controls.Button]::BackgroundProperty, 'AccentBrush')
        $OrbCore.Fill = $script:OrbOff; $OrbGlyph.Foreground = $Win.Resources['SubBrush']; Set-Pulse $false; $OrbCore.Effect = $null
        $BtnToggle.IsEnabled = [bool]$script:Selected
    }
    if ($script:Alert) {
        $at = $script:Alert.Title.Substring(0, 1).ToUpper() + $script:Alert.Title.Substring(1)
        $txt = $at + "`n" + (($script:Alert.Lines) -join "`n")
        if ($script:Alert.Fix) { $txt += "`n" + $script:Alert.Fix }
        $AlertText.Text = $txt
        $AlertBox.Visibility = 'Visible'
        if ($script:Running -and -not $script:Testing) {
            $StatusText.Text = 'Проблема со связью'; $StatusText.Foreground = $Win.Resources['DangerBrush']; $OrbCore.Fill = $script:OrbAlert
        } elseif (-not $script:Running -and -not $script:Starting -and -not $script:Testing) {
            $StatusText.Text = 'Обход остановился'; $StatusText.Foreground = $Win.Resources['DangerBrush']
        }
    } else { $AlertBox.Visibility = 'Collapsed' }
    if (-not $script:Running) { $MonText.Text = '' }
    $BtnRestart.IsEnabled = [bool]($script:Selected -or $script:Active -or $script:LastStrategy)
    if ($script:Tray) {
        Update-TrayText
        $script:TrayToggle.Text = if ($script:Running) { 'Остановить' } else { 'Запустить последнюю' }
    }
    Update-TrayIcon
    Cards-Refresh
}

# ---------------------------------------------------------------- подбор по приоритету
$script:AutoLabel = [string][char]0x2728 + '  Подбор под мои задачи'
$script:Services = @(
    @{ Key = 'yt'; Name = 'YouTube'; Short = 'YT'; Sub = 'сайт, превью, видеосервера'; Urls = @('https://www.youtube.com', 'https://i.ytimg.com', 'https://redirector.googlevideo.com') },
    @{ Key = 'dc'; Name = 'Discord'; Short = 'DC'; Sub = 'сайт, gateway, CDN'; Urls = @('https://discord.com', 'https://gateway.discord.gg', 'https://cdn.discordapp.com') },
    @{ Key = 'tg'; Name = 'Telegram'; Short = 'TG'; Sub = 'сайт и web-версия'; Urls = @('https://telegram.org', 'https://web.telegram.org') },
    @{ Key = 'ig'; Name = 'Instagram'; Short = 'IG'; Sub = 'сайт и CDN'; Urls = @('https://www.instagram.com', 'https://static.cdninstagram.com') },
    @{ Key = 'x'; Name = 'X (Twitter)'; Short = 'X'; Sub = 'сайт и картинки'; Urls = @('https://x.com', 'https://abs.twimg.com') },
    @{ Key = 'tw'; Name = 'Twitch'; Short = 'TW'; Sub = 'сайт и CDN'; Urls = @('https://www.twitch.tv', 'https://static-cdn.jtvnw.net') },
    @{ Key = 'cf'; Name = 'Cloudflare'; Short = 'CF'; Sub = 'сайты за Cloudflare'; Urls = @('https://www.cloudflare.com', 'https://cdnjs.cloudflare.com') }
)

$prioRowXaml = @'
<Border xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Style="{DynamicResource CardStyle}" Padding="12,9">
  <Grid>
    <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
    <CheckBox x:Name="Chk" Style="{DynamicResource Switch}" VerticalAlignment="Center" Margin="0,0,14,0"/>
    <StackPanel Grid.Column="1" VerticalAlignment="Center">
      <TextBlock x:Name="Ttl" FontWeight="SemiBold"/>
      <TextBlock x:Name="Sub" FontSize="11" Foreground="{DynamicResource SubBrush}" Margin="0,2,0,0"/>
    </StackPanel>
    <TextBlock x:Name="Star" Grid.Column="2" FontFamily="Segoe UI Symbol" FontSize="20" VerticalAlignment="Center" Cursor="Hand" Padding="10,0,0,0" ToolTip="Главный сервис: его вес в 2 раза больше"/>
  </Grid>
</Border>
'@
$prioRowXaml = Scale-Xaml $prioRowXaml

$script:PrioRows = @{}
$script:ResRows = @{}
$script:ResChoice = $null

function Get-CustomUrls([string]$t) {
    $r = @()
    foreach ($p in ($t -split '[,;\s]+')) {
        if (-not $p) { continue }
        if ($p -notmatch '^https?://') { $p = 'https://' + $p }
        $u = $null
        if ([Uri]::TryCreate($p, [UriKind]::Absolute, [ref]$u)) { $r += $u.AbsoluteUri }
    }
    $r
}

function Update-PrioEta {
    $n = 0
    foreach ($k in $script:PrioRows.Keys) { if ($script:PrioRows[$k].Chk.IsChecked) { $n++ } }
    $cnt = $script:Strategies.Count
    $per = 7; if ($script:PrioMode -eq 'full') { $per = 11 }
    if ($script:PrioMode -eq 'urgent') { $PrioEta.Text = ('Стратегий: {0}  ·  остановится на первой подходящей (в худшем случае до {1} мин)' -f $cnt, [Math]::Ceiling($cnt * $per / 60.0)) }
    else { $PrioEta.Text = ('Стратегий: {0}  ·  примерно до {1} мин' -f $cnt, [Math]::Ceiling($cnt * $per / 60.0)) }
    $BtnPrioStart.IsEnabled = ($script:PrioMode -eq 'full') -or ($n -gt 0) -or (@(Get-CustomUrls $PrioCustom.Text).Count -gt 0)
}

$script:PrioMode = 'target'
function Set-PrioMode([string]$m) {
    $script:PrioMode = $m
    switch ($m) {
        'full' { $ModeDesc.Text = 'Проверяет все стратегии на все сервисы из списка (отметки не нужны). Самый долгий режим, зато самая полная картина.'; $BtnPrioStart.Content = 'Начать проверку' }
        'urgent' { $ModeDesc.Text = 'Ищет стратегию для отмеченных сервисов и сразу подключает первую, которая открывает их все. Дальше не проверяет.'; $BtnPrioStart.Content = 'Найти и подключить' }
        default { $ModeDesc.Text = 'Проверяет все стратегии, но только на отмеченных сервисах, и показывает рейтинг. Сама ничего не подключает.'; $BtnPrioStart.Content = 'Начать проверку' }
    }
    if ($m -eq 'full') { $PrioList.Opacity = 0.4; $PrioList.IsHitTestVisible = $false } else { $PrioList.Opacity = 1; $PrioList.IsHitTestVisible = $true }
    Update-PrioEta
}

function Prio-RefreshStar([string]$key) {
    $row = $script:PrioRows[$key]
    if (@($Cfg.PrioMain) -contains $key) { $row.Star.Text = [string][char]0x2605; $row.Star.Foreground = New-Brush (ToColor '#FFC83D') }
    else { $row.Star.Text = [string][char]0x2606; $row.Star.Foreground = $Win.Resources['SubBrush'] }
}

function Show-PrioDialog {
    if ($script:Strategies.Count -eq 0) { Log 'Нет стратегий для проверки'; return }
    $PrioList.Children.Clear(); $script:PrioRows = @{}
    foreach ($s in $script:Services) {
        $row = [Windows.Markup.XamlReader]::Parse($prioRowXaml)
        $row.Tag = $s.Key
        $row.FindName('Ttl').Text = $s.Name
        $row.FindName('Sub').Text = $s.Sub
        $chk = $row.FindName('Chk'); $chk.Tag = $s.Key
        $chk.IsChecked = (@($Cfg.PrioServices) -contains $s.Key)
        $chk.Add_Click({ Update-PrioEta })
        $star = $row.FindName('Star'); $star.Tag = $s.Key
        $star.Add_MouseLeftButtonUp({ param($sender, $ev)
            $ev.Handled = $true
            $k = [string]$sender.Tag
            $m = @($Cfg.PrioMain)
            if ($m -contains $k) { $m = @($m | Where-Object { $_ -ne $k }) } else { $m += $k; $script:PrioRows[$k].Chk.IsChecked = $true }
            $Cfg.PrioMain = $m
            Prio-RefreshStar $k; Update-PrioEta })
        $row.Add_MouseLeftButtonUp({ param($sender, $ev)
            $r = $script:PrioRows[[string]$sender.Tag]
            $r.Chk.IsChecked = -not [bool]$r.Chk.IsChecked
            Update-PrioEta })
        $script:PrioRows[$s.Key] = @{ Chk = $chk; Star = $star }
        [void]$PrioList.Children.Add($row)
        Prio-RefreshStar $s.Key
    }
    $PrioCustom.Text = [string]$Cfg.PrioCustom
    $pm = [string]$Cfg.TestMode
    switch ($pm) { 'full' { $ModeFull.IsChecked = $true } 'urgent' { $ModeUrgent.IsChecked = $true } default { $pm = 'target'; $ModeTarget.IsChecked = $true } }
    Set-PrioMode $pm
    Update-PrioEta
    $ResultPanel.Visibility = 'Collapsed'; $PrioPanel.Visibility = 'Visible'; $Overlay.Visibility = 'Visible'
}

function Show-About {
    $PrioPanel.Visibility = 'Collapsed'; $ResultPanel.Visibility = 'Collapsed'; $RenamePanel.Visibility = 'Collapsed'
    $AboutPanel.Visibility = 'Visible'; $Overlay.Visibility = 'Visible'
}

function Hide-Overlay { $AboutPanel.Visibility = 'Collapsed'; $RenamePanel.Visibility = 'Collapsed'; $Overlay.Visibility = 'Collapsed'; $PrioPanel.Visibility = 'Collapsed'; $ResultPanel.Visibility = 'Collapsed' }

function Res-Select([string]$name) {
    $script:ResChoice = $name
    $ResBest.Text = Disp $name
    if ($Results.ContainsKey($name)) { $ResBestSub.Text = $Results[$name] } else { $ResBestSub.Text = '' }
    foreach ($k in $script:ResRows.Keys) {
        if ($k -eq $name) { $script:ResRows[$k].SetResourceReference([Windows.Controls.Border]::BorderBrushProperty, 'AccentBrush') }
        else { $script:ResRows[$k].BorderBrush = [Windows.Media.Brushes]::Transparent }
    }
}

function Show-Result($rank, $scores) {
    $ResList.Children.Clear(); $script:ResRows = @{}
    $best = $rank | Select-Object -First 1
    $ok = $best -and ([double]$scores[$best] -gt 0)
    if (-not $ok) {
        $ResTitle.Text = 'ИТОГ ПРОВЕРКИ'
        $ResBest.Text = 'Ничего не подошло'
        $ResBestSub.Text = 'Ни одна стратегия не открыла выбранные сервисы. Попробуйте выбрать другие сервисы или проверьте интернет-соединение.'
        $BtnResRun.Visibility = 'Collapsed'
    } else {
        $ResTitle.Text = 'РЕКОМЕНДУЕМ'
        $BtnResRun.Visibility = 'Visible'
        $top = @($rank | Where-Object { [double]$scores[$_] -gt 0 } | Select-Object -First 4)
        foreach ($n in $top) {
            $card = [Windows.Markup.XamlReader]::Parse($cardXaml)
            $card.Cursor = [Windows.Input.Cursors]::Hand
            Set-CardTitle $card.FindName('Title') $n
            if ($Results.ContainsKey($n)) { $card.FindName('Sub').Text = $Results[$n] }
            $st = $card.FindName('Star'); $st.Text = ('{0}%' -f [int][Math]::Round(100 * [double]$scores[$n]))
            $st.FontFamily = New-Object System.Windows.Media.FontFamily 'Segoe UI'; $st.FontSize = 14; $st.FontWeight = 'Bold'
            $st.SetResourceReference([Windows.Controls.TextBlock]::ForegroundProperty, 'AccentBrush')
            $card.Tag = $n
            $card.Add_MouseLeftButtonUp({ param($sender, $ev) Res-Select ([string]$sender.Tag) })
            $script:ResRows[$n] = $card
            [void]$ResList.Children.Add($card)
        }
        Res-Select $best
    }
    $PrioPanel.Visibility = 'Collapsed'; $ResultPanel.Visibility = 'Visible'; $Overlay.Visibility = 'Visible'
}

$script:T = $null
$script:TestTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:TestTimer.Interval = [TimeSpan]::FromMilliseconds(250)
$script:TestWarmMs = 1500

function Stop-Test {
    $script:TestTimer.Stop(); $script:Testing = $false
    $script:KeepArmed = $false; $script:KeepRetryAt = $null
    [ZNative]::KeepAwake($false)
    if ($script:T -and $script:T.Client) { try { $script:T.Client.Dispose() } catch { } }
    $script:T = $null
    $ProgTrack.Visibility = 'Collapsed'; $BtnAuto.Content = $script:AutoLabel
    Log 'Подбор остановлен'
}

function Test-WinwsUp {
    $p = [Diagnostics.Process]::GetProcessesByName('winws')
    $r = ($p.Count -gt 0)
    foreach ($x in $p) { $x.Dispose() }
    return $r
}

function Test-Fail($T, [string]$name, [string]$why) {
    $T.Scores[$name] = 0.0
    $Results[$name] = $why
    Log ((Disp $name) + ': ' + $why)
    Card-Refresh $name
    $T.Phase = 'next'
}

function Start-Test {
    if ($script:Strategies.Count -eq 0) { return }
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    $svcs = @()
    $mode = [string]$Cfg.TestMode
    foreach ($s in $script:Services) {
        if ($mode -eq 'full' -or (@($Cfg.PrioServices) -contains $s.Key)) {
            $w = 1; if (@($Cfg.PrioMain) -contains $s.Key) { $w = 2 }
            $svcs += @{ Key = $s.Key; Name = $s.Name; Short = $s.Short; Urls = $s.Urls; Weight = $w }
        }
    }
    $cu = @(Get-CustomUrls ([string]$Cfg.PrioCustom))
    if ($cu.Count -gt 0) { $svcs += @{ Key = 'custom'; Name = 'Свой сайт'; Short = 'сайт'; Urls = $cu; Weight = 1 } }
    if ($svcs.Count -eq 0) { return }
    # проверка связи не должна вмешиваться в подбор (иначе она может перезапустить стратегию посреди теста)
    if ($script:Mon) { try { $script:Mon.Client.Dispose() } catch { }; $script:Mon = $null }
    $script:NextCheck = $null; $script:MonConfirm = $false
    $script:KeepArmed = $false; $script:KeepRetryAt = $null; $script:RestartAt = $null
    Clear-Alert
    # сначала проверяем избранные и те, что раньше хорошо себя показали: при быстром подборе это даёт результат за секунды
    $q = @($script:Strategies | Sort-Object @{ Expression = { if (@($Cfg.Favorites) -contains $_.Name) { 0 } elseif ((Get-Pct $_.Name) -ge 80) { 1 } else { 2 } } }, @{ Expression = { Sort-Key $_.Name } } | ForEach-Object { $_.Name })
    # заранее прогреваем DNS, чтобы первые стратегии не проигрывали во времени
    foreach ($s in $svcs) { foreach ($u in $s.Urls) { try { [void][Net.Dns]::GetHostEntryAsync(([Uri]$u).Host) } catch { } } }
    $script:T = @{ Queue = $q; Index = 0; Phase = 'begin'; Until = Get-Date; Tasks = $null; Client = $null; Svcs = $svcs; Scores = @{}; Seen = $null; DownAt = $null; Stop = $false; Errors = 0; Mode = $mode; Found = $null }
    $script:Testing = $true
    [ZNative]::KeepAwake($true)
    $BtnAuto.Content = 'Остановить подбор'
    $ProgTrack.Visibility = 'Visible'; $ProgFill.Width = 0
    $modeName = switch ($mode) { 'full' { 'полная проверка' } 'urgent' { 'срочная проверка' } default { 'только нужная' } }
    Log ('Подбор ({0}): {1} стратегий, сервисы: {2}' -f $modeName, $q.Count, (($svcs | ForEach-Object { $_.Name }) -join ', '))
    $script:TestTimer.Start()
    Render-State
}

function Finish-Test {
    $T = $script:T
    $script:TestTimer.Stop(); $script:Testing = $false; $script:T = $null
    [ZNative]::KeepAwake($false)
    $ProgTrack.Visibility = 'Collapsed'; $BtnAuto.Content = $script:AutoLabel
    if ($T.Found) {
        # срочная проверка: найденная стратегия остаётся включённой
        $n = $T.Found
        $script:Selected = $n; $Cfg.Last = $n
        $AutoText.Text = ('Подключено: {0}' -f (Disp $n))
        $script:NextCheck = (Get-Date).AddSeconds(20)
        $script:KeepArmed = $true; $script:KeepGoodName = $n; $script:LastStrategy = $n
        Save-Settings
        Log ('Подключено: ' + (Disp $n))
        Balloon 'Zapret Studio' ('Подключено: ' + (Disp $n)) ([Windows.Forms.ToolTipIcon]::Info)
        if ($Cfg.Sort -eq 'score') { Rebuild-List }
        Cards-Refresh; Render-State
        return
    }
    $script:KeepArmed = $false
    Stop-Zapret
    $scores = $T.Scores
    $rank = @($T.Queue | Sort-Object @{ Expression = { -[double]$scores[$_] } }, @{ Expression = { if (@($Cfg.Favorites) -contains $_) { 0 } else { 1 } } }, @{ Expression = { Sort-Key $_ } })
    Save-Settings
    $best = $rank | Select-Object -First 1
    if ($best -and [double]$scores[$best] -gt 0) { $AutoText.Text = ('Лучшая: {0}  ({1}%)' -f (Disp $best), [int][Math]::Round(100 * [double]$scores[$best])) }
    else { $AutoText.Text = 'Ни одна стратегия не подошла' }
    Log $AutoText.Text
    if ($Cfg.Sort -eq 'score') { Rebuild-List }
    Cards-Refresh; Render-State
    Show-Result $rank $scores
}

$script:TestTimer.Add_Tick({
    $T = $script:T; if (-not $T) { return }
    $name = $T.Queue[$T.Index]
    $total = $T.Queue.Count
    # любая ошибка внутри шага не обрывает подбор: стратегия засчитывается как неудачная, и мы идём дальше
    try {
        switch ($T.Phase) {
            'begin' {
                $AutoText.Text = ('Тест {0}/{1}: {2}' -f ($T.Index + 1), $total, (Disp $name))
                $ProgFill.Width = $ProgTrack.ActualWidth * ($T.Index / $total)
                $script:Selected = $name
                $T.Seen = $null; $T.DownAt = $null
                Start-Strategy $name
                $T.Phase = 'wait'; $T.Until = (Get-Date).AddSeconds(6)
            }
            'wait' {
                $now = Get-Date
                if (Test-WinwsUp) {
                    if ($T.DownAt -or -not $T.Seen) { $T.Seen = $now }
                    $T.DownAt = $null
                    $script:Running = $true; $script:Starting = $false
                    if (-not $script:StartedAt) { $script:StartedAt = $now }
                    # winws должен прогреться (открыть WinDivert), но ждём не фиксированные 5 секунд, а только 1.5 с после его появления
                    if (($now - $T.Seen).TotalMilliseconds -ge $script:TestWarmMs) {
                        $c = New-Object System.Net.Http.HttpClient
                        $c.Timeout = [TimeSpan]::FromSeconds(5)
                        try { $c.DefaultRequestHeaders.UserAgent.ParseAdd('Mozilla/5.0 (Windows NT 10.0; Win64; x64)') } catch { }
                        $T.Client = $c
                        $tasks = @()
                        foreach ($s in $T.Svcs) {
                            foreach ($u in $s.Urls) { $tasks += @{ Svc = $s.Key; Task = $c.GetAsync($u, [Net.Http.HttpCompletionOption]::ResponseHeadersRead) } }
                        }
                        $T.Tasks = $tasks
                        $T.Phase = 'http'; $T.Until = $now.AddSeconds(6.5)
                    }
                } else {
                    if ($T.Seen) {
                        if (-not $T.DownAt) { $T.DownAt = $now }
                        elseif (($now - $T.DownAt).TotalSeconds -ge 1.5) { Test-Fail $T $name 'вылетела при запуске'; return }
                    }
                    if ($now -ge $T.Until) { Test-Fail $T $name 'не запустилась' }
                }
            }
            'http' {
                $done = @($T.Tasks | Where-Object { $_.Task.IsCompleted }).Count
                if ($done -ge $T.Tasks.Count -or (Get-Date) -ge $T.Until) {
                    $score = 0.0; $wsum = 0.0; $parts = @()
                    foreach ($s in $T.Svcs) {
                        $mine = @($T.Tasks | Where-Object { $_.Svc -eq $s.Key })
                        $okc = @($mine | Where-Object { $_.Task.Status -eq 'RanToCompletion' }).Count
                        $score += $s.Weight * ($okc / [double]$mine.Count); $wsum += $s.Weight
                        $parts += ('{0} {1}/{2}' -f $s.Short, $okc, $mine.Count)
                    }
                    try { $T.Client.Dispose() } catch { }
                    $T.Client = $null
                    $frac = $score / $wsum
                    $T.Scores[$name] = $frac
                    $Results[$name] = ('{0}%  ·  {1}' -f [int][Math]::Round(100 * $frac), ($parts -join '  '))
                    Log ('{0}: {1}' -f (Disp $name), $Results[$name])
                    Card-Refresh $name
                    if ($T.Mode -eq 'urgent' -and $frac -ge 0.999) {
                        $T.Stop = $true; $T.Found = $name
                        Log ('Срочный подбор завершён досрочно: «{0}» открывает всё на 100%, подключаю' -f (Disp $name))
                    }
                    $T.Phase = 'next'
                }
            }
            'next' {
                $T.Index++
                if ($T.Index -ge $total -or $T.Stop) { Finish-Test } else { $T.Phase = 'begin' }
            }
        }
    } catch {
        $em = $_.Exception.Message
        try { Log ('Ошибка при проверке «{0}»: {1}. Иду дальше.' -f (Disp $name), $em) } catch { }
        try { if ($T.Client) { $T.Client.Dispose() } } catch { }
        $T.Client = $null
        $T.Errors = [int]$T.Errors + 1
        $T.Scores[$name] = 0.0
        $Results[$name] = 'ошибка проверки'
        $T.Phase = 'next'
    }
})


# ---------------------------------------------------------------- оформление: контролы
$script:Sync = $false
$AccentPresets = @(
    @('#7C5CFF', 'Фиолетовый'), @('#3B82F6', 'Синий'), @('#06B6D4', 'Бирюзовый'), @('#10B981', 'Изумрудный'), @('#84CC16', 'Лайм'),
    @('#F59E0B', 'Янтарный'), @('#F97316', 'Оранжевый'), @('#F43F5E', 'Роза'), @('#EC4899', 'Розовый'), @('#D946EF', 'Фуксия'))
$BgPresets = @(
    @('#12121A', 'Тёмная'), @('#0A1022', 'Полночь'), @('#1B1C1F', 'Графит'), @('#0D1A14', 'Лес'),
    @('#1C0F16', 'Бордо'), @('#1D1612', 'Мокко'), @('#000000', 'Чёрная'), @('#EEF0F6', 'Светлая'), @('#FFFFFF', 'Белая'))

$script:DotInfo = @()
function New-Dot([string]$hex, [string]$tip, [string]$kind) {
    $b = New-Object System.Windows.Controls.Border
    $b.Width = 30; $b.Height = 30
    $b.CornerRadius = New-Object System.Windows.CornerRadius 15
    $b.Margin = New-Object System.Windows.Thickness 0, 0, 8, 8
    $b.BorderThickness = New-Object System.Windows.Thickness 2.5
    $b.Background = New-Brush (ToColor $hex)
    $b.Cursor = [Windows.Input.Cursors]::Hand
    $b.ToolTip = $tip
    $b.Tag = "$kind|$hex"
    $b.Add_MouseLeftButtonUp({ param($sender, $ev)
        $p = $sender.Tag.Split('|')
        switch ($p[0]) { 'a' { Set-Accent $p[1] } 'b' { Set-Bg $p[1] } 't' { Set-TextColor $p[1] } } })
    $script:DotInfo += @{ El = $b; Kind = $kind; Hex = $hex }
    $b
}
foreach ($p in $AccentPresets) { [void]$AccentDots.Children.Add((New-Dot $p[0] $p[1] 'a')) }
foreach ($p in $BgPresets) { [void]$BgDots.Children.Add((New-Dot $p[0] $p[1] 'b')) }

# ---------------------------------------------------------------- шрифт
$TextPresets = @(@('#FFFFFF', 'Белый'), @('#E5E7EB', 'Светло-серый'), @('#FDE7C8', 'Тёплый'), @('#CFE3FF', 'Голубоватый'), @('#FBCFE8', 'Розоватый'), @('#9CA3AF', 'Серый'), @('#374151', 'Графит'), @('#151821', 'Чёрный'))
foreach ($p in $TextPresets) { [void]$TextDots.Children.Add((New-Dot $p[0] $p[1] 't')) }
$script:Installed = @{}
foreach ($f in [Windows.Media.Fonts]::SystemFontFamilies) { $script:Installed[$f.Source.ToLower()] = $f.Source }
$script:Chips = @()
foreach ($fn in 'Segoe UI', 'Bahnschrift', 'Calibri', 'Candara', 'Corbel', 'Arial', 'Tahoma', 'Verdana', 'Trebuchet MS', 'Georgia', 'Cambria', 'Consolas', 'Comic Sans MS') {
    if (-not $script:Installed.ContainsKey($fn.ToLower())) { continue }
    $r = New-Object System.Windows.Controls.RadioButton
    $r.Style = $Win.FindResource('Seg'); $r.Content = $fn; $r.GroupName = 'fnt'
    $r.FontFamily = New-Object System.Windows.Media.FontFamily $fn
    $r.Padding = New-Object System.Windows.Thickness 12, 6, 12, 6
    $r.Margin = New-Object System.Windows.Thickness 0, 0, 6, 6
    $r.SetResourceReference([Windows.Controls.Control]::FontSizeProperty, 'Fs13')
    if ($fn -eq 'Segoe UI') { $r.Tag = '' } else { $r.Tag = $fn }
    $r.Add_Click({ param($sender, $ev) Set-FontName ([string]$sender.Tag) })
    $script:Chips += $r
    [void]$FontChips.Children.Add($r)
}
$script:FSync = $false
function Apply-Font {
    $name = 'Segoe UI'
    if ($Cfg.Font -and $script:Installed.ContainsKey(([string]$Cfg.Font).ToLower())) { $name = $script:Installed[([string]$Cfg.Font).ToLower()] }
    try { $Win.FontFamily = New-Object System.Windows.Media.FontFamily $name } catch { }
    Set-FsRes
}
function Sync-Font {
    $script:FSync = $true
    try {
        $hit = $false
        foreach ($c in $script:Chips) { $on = ([string]$c.Tag -ieq [string]$Cfg.Font); $c.IsChecked = $on; if ($on) { $hit = $true } }
        if ($hit) { $FontBox.Text = '' } elseif ($FontBox.Text -ine $Cfg.Font) { $FontBox.Text = [string]$Cfg.Font }
        $SlFont.Minimum = 80; $SlFont.Maximum = 130; $SlFont.TickFrequency = 5; $SlFont.IsSnapToTickEnabled = $true
        $SlFont.Value = [double]$Cfg.FontScale; $LbSlFont.Text = ('{0}%' -f [int]$Cfg.FontScale)
        if ($HexText.Text -ine $Cfg.TextColor) { $HexText.Text = [string]$Cfg.TextColor }
        $ChkCompact.IsChecked = [bool]$Cfg.Compact; $ChkDesc.IsChecked = [bool]$Cfg.ShowDesc
    } finally { $script:FSync = $false }
    Update-Dots
}
function Set-FontName([string]$n) { $Cfg.Font = $n; Apply-Font; Sync-Font; Request-Save }
function Set-TextColor([string]$hex) {
    if ($hex -and $hex -notmatch '^#[0-9A-Fa-f]{6}$') { return }
    $Cfg.TextColor = $hex.ToUpper(); Queue-Theme; Sync-Font; Request-Save
}
$script:FontTimer = New-Object System.Windows.Threading.DispatcherTimer
$script:FontTimer.Interval = [TimeSpan]::FromMilliseconds(90)
$script:FontTimer.Add_Tick({ $script:FontTimer.Stop(); Set-FsRes })
$SlFont.Add_ValueChanged({
    if (-not $script:Ready -or $script:FSync) { return }
    $v = [int]([Math]::Round($SlFont.Value / 5) * 5)
    $Cfg.FontScale = $v; $LbSlFont.Text = ('{0}%' -f $v)
    $script:FontTimer.Stop(); $script:FontTimer.Start(); Request-Save
})
$FontBox.Add_TextChanged({
    if (-not $script:Ready -or $script:FSync) { return }
    $k = $FontBox.Text.Trim().ToLower()
    if ($k -and $script:Installed.ContainsKey($k)) { $Cfg.Font = $script:Installed[$k]; Apply-Font; $script:FSync = $true; foreach ($c in $script:Chips) { $c.IsChecked = ([string]$c.Tag -ieq [string]$Cfg.Font) }; $script:FSync = $false; Update-Dots; Request-Save }
})
$HexText.Add_TextChanged({ if ($script:Ready -and -not $script:FSync -and $HexText.Text -match '^#[0-9A-Fa-f]{6}$') { Set-TextColor $HexText.Text } })
$BtnTextAuto.Add_Click({ Set-TextColor '' })
$ChkCompact.Add_Click({ $Cfg.Compact = [bool]$ChkCompact.IsChecked; Cards-Refresh; Request-Save })
$ChkDesc.Add_Click({ $Cfg.ShowDesc = [bool]$ChkDesc.IsChecked; Cards-Refresh; Request-Save })
$BtnResetFont.Add_Click({ $Cfg.Font = ''; $Cfg.FontScale = 100; $Cfg.TextColor = ''; Apply-Font; Queue-Theme; Sync-Font; Request-Save })

function Update-Labels {
    $LbSlR.Text = [string][int]$SlR.Value; $LbSlG.Text = [string][int]$SlG.Value; $LbSlB.Text = [string][int]$SlB.Value
    $LbSlOpacity.Text = ('{0}%' -f [int]$SlOpacity.Value); $LbSlPanel.Text = ('{0}%' -f [int]$SlPanel.Value)
    $LbSlGrad.Text = ('{0}%' -f [int]$SlGrad.Value); $LbSlRadius.Text = ('{0}px' -f [int]$SlRadius.Value)
}

function Update-Dots {
    $on = $Win.Resources['TextBrush']; $off = $Win.Resources['StrokeBrush']
    foreach ($d in $script:DotInfo) {
        switch ($d.Kind) { 'a' { $cur = $Cfg.Accent } 'b' { $cur = $Cfg.Bg } default { $cur = $Cfg.TextColor } }
        if ($d.Hex -ieq $cur) { $d.El.BorderBrush = $on } else { $d.El.BorderBrush = $off }
    }
}

function Sync-Look([switch]$SkipRgb, [switch]$Light) {
    $script:Sync = $true
    try {
        if (-not $SkipRgb) { $c = ToColor $Cfg.Accent; $SlR.Value = $c.R; $SlG.Value = $c.G; $SlB.Value = $c.B }
        if ($HexAccent.Text -ine $Cfg.Accent) { $HexAccent.Text = $Cfg.Accent }
        if ($HexBg.Text -ine $Cfg.Bg) { $HexBg.Text = $Cfg.Bg }
        if (-not $Light) {
            $SlOpacity.Value = [double]$Cfg.WindowOpacity * 100
            $SlPanel.Value = [double]$Cfg.PanelAlpha * 100
            $SlGrad.Value = [double]$Cfg.Gradient * 100
            $SlRadius.Value = [double]$Cfg.Radius
            $ChkGlow.IsChecked = [bool]$Cfg.Glow; $ChkBlur.IsChecked = [bool]$Cfg.Blur; $ChkPerf.IsChecked = [bool]$Cfg.Perf
        }
        Update-Labels
    } finally { $script:Sync = $false }
    Update-Dots
}

function Set-Accent([string]$hex, [switch]$SkipRgb) {
    if ($hex -notmatch '^#[0-9A-Fa-f]{6}$') { return }
    $Cfg.Accent = $hex.ToUpper(); Queue-Theme
    if ($SkipRgb) { Sync-Look -SkipRgb -Light } else { Sync-Look }
    Request-Save
}
function Set-Bg([string]$hex) {
    if ($hex -notmatch '^#[0-9A-Fa-f]{6}$') { return }
    $Cfg.Bg = $hex.ToUpper(); Queue-Theme; Sync-Look; Request-Save
}

function Look-Changed {
    if (-not $script:Ready -or $script:Sync) { return }
    $Cfg.WindowOpacity = [Math]::Round($SlOpacity.Value / 100, 2)
    $Cfg.PanelAlpha = [Math]::Round($SlPanel.Value / 100, 2)
    $Cfg.Gradient = [Math]::Round($SlGrad.Value / 100, 2)
    $Cfg.Radius = [int]$SlRadius.Value
    Update-Labels; Queue-Theme; Request-Save
}
foreach ($sl in $SlOpacity, $SlPanel, $SlGrad, $SlRadius) { $sl.Add_ValueChanged({ Look-Changed }) }
foreach ($sl in $SlR, $SlG, $SlB) {
    $sl.Add_ValueChanged({
        if (-not $script:Ready -or $script:Sync) { return }
        Update-Labels
        Set-Accent ('#{0:X2}{1:X2}{2:X2}' -f [int]$SlR.Value, [int]$SlG.Value, [int]$SlB.Value) -SkipRgb
    })
}
$HexAccent.Add_TextChanged({ if ($script:Ready -and -not $script:Sync) { Set-Accent $HexAccent.Text } })
$HexBg.Add_TextChanged({ if ($script:Ready -and -not $script:Sync) { Set-Bg $HexBg.Text } })
$ChkGlow.Add_Click({ $Cfg.Glow = [bool]$ChkGlow.IsChecked; Apply-Theme -Full; Request-Save })
$ChkBlur.Add_Click({ $Cfg.Blur = [bool]$ChkBlur.IsChecked; Apply-Theme -Full; Request-Save })
$ChkPerf.Add_Click({ $Cfg.Perf = [bool]$ChkPerf.IsChecked; Apply-Theme -Full; Request-Save })
$BtnResetLook.Add_Click({
    foreach ($k in 'Accent', 'Bg', 'WindowOpacity', 'PanelAlpha', 'Radius', 'Gradient', 'Glow', 'Blur') { $Cfg[$k] = $Defaults[$k] }
    Apply-Theme -Full; Sync-Look; Request-Save
})

# ---------------------------------------------------------------- слежение за связью
$script:Alert = $null; $script:Mon = $null; $script:NextCheck = $null; $script:MonConfirm = $false
$script:FixTried = @(); $script:LastStrategy = $null
$script:CtlUrl = 'http://www.msftconnecttest.com/connecttest.txt'
$script:OrbAlert = New-Object System.Windows.Media.RadialGradientBrush
$script:OrbAlert.GradientOrigin = New-Object System.Windows.Point 0.35, 0.3
$script:OrbAlert.GradientStops.Add((GStop (ToColor '#FF8A8A') 0))
$script:OrbAlert.GradientStops.Add((GStop (ToColor '#EF4444') 0.75))
$script:OrbAlert.GradientStops.Add((GStop (ToColor '#9F1D1D') 1))

function Get-MonSvcs {
    $keys = @($Cfg.PrioServices)
    if ($keys.Count -eq 0 -and -not $Cfg.PrioCustom) { $keys = @('yt', 'dc') }
    $r = @()
    foreach ($s in $script:Services) { if ($keys -contains $s.Key) { $r += @{ Key = $s.Key; Name = $s.Name; Urls = $s.Urls } } }
    $cu = @(Get-CustomUrls ([string]$Cfg.PrioCustom))
    if ($cu.Count -gt 0) { $r += @{ Key = 'custom'; Name = 'Свой сайт'; Urls = $cu } }
    $r
}

function Get-FailReason($task) {
    try {
        if ($task.Status -eq 'Canceled') { return 'таймаут: сервер не отвечает' }
        if ($task.Status -eq 'Faulted') {
            $e = $task.Exception; $web = $null
            while ($e) { if ($e -is [System.Net.WebException]) { $web = $e; break }; $e = $e.InnerException }
            if ($web) {
                switch ([string]$web.Status) {
                    'NameResolutionFailure' { return 'DNS не отвечает (адрес не найден)' }
                    'ConnectFailure' { return 'не удаётся подключиться' }
                    'ReceiveFailure' { return 'соединение сброшено (похоже на блокировку DPI)' }
                    'SendFailure' { return 'соединение сброшено при отправке' }
                    'ConnectionClosed' { return 'соединение закрыто сервером' }
                    'SecureChannelFailure' { return 'ошибка TLS: рукопожатие сорвано (блокировка)' }
                    'TrustFailure' { return 'ошибка сертификата (возможна подмена)' }
                    'Timeout' { return 'таймаут' }
                }
                return 'ошибка: ' + $web.Message
            }
            return 'ошибка: ' + $task.Exception.GetBaseException().Message
        }
        return 'таймаут: нет ответа'
    } catch { return 'неизвестная ошибка' }
}

function Get-RankedNames {
    $r = @()
    foreach ($k in $Results.Keys) { if ($Results[$k] -match '^(\d+)%') { $r += [pscustomobject]@{ N = $k; P = [int]$Matches[1] } } }
    @($r | Sort-Object @{ Expression = { -$_.P } }, @{ Expression = { Sort-Key $_.N } } | ForEach-Object { $_.N })
}

function Update-TrayText {
    if (-not $script:Tray) { return }
    if ($script:Alert) { $t = 'Zapret Studio — СБОЙ: ' + $script:Alert.Title }
    elseif ($script:Running) { $t = 'Zapret Studio — активно' }
    else { $t = 'Zapret Studio — выключено' }
    if ($t.Length -gt 62) { $t = $t.Substring(0, 62) }
    $script:Tray.Text = $t
}

function Balloon([string]$title, [string]$text, $icon) {
    try { $script:Tray.ShowBalloonTip(8000, $title, $text, $icon) } catch { }
}

function Set-Alert([string]$title, [string[]]$lines) {
    $new = (-not $script:Alert) -or ($script:Alert.Title -ne $title)
    $fix = ''; if ($script:Alert) { $fix = $script:Alert.Fix }
    $script:Alert = @{ Title = $title; Lines = @($lines); Fix = $fix; Time = Get-Date }
    if ($new) {
        Log ('ПРОБЛЕМА: ' + $title)
        foreach ($l in $lines) { Log ('   ' + $l) }
        $first = ''; if ($lines.Count -gt 0) { $first = $lines[0] }
        Balloon 'Zapret Studio: сбой' ($title + "`n" + $first) ([Windows.Forms.ToolTipIcon]::Error)
    }
    Render-State
}

function Clear-Alert([switch]$Recovered) {
    if (-not $script:Alert) { return }
    $script:Alert = $null; $script:FixTried = @(); $script:MonConfirm = $false
    if ($Recovered) {
        Log 'Связь восстановлена'
        Balloon 'Zapret Studio' 'Связь восстановлена, всё работает.' ([Windows.Forms.ToolTipIcon]::Info)
    }
    Render-State
}

# кандидаты для автовосстановления: сначала лучшие по результатам подбора, потом избранные, потом ещё не проверявшиеся (0% пропускаем)
function Get-FixCandidates {
    $r = @(Get-RankedNames | Where-Object { (Get-Pct $_) -gt 0 })
    $fav = @($script:Strategies | Where-Object { (@($Cfg.Favorites) -contains $_.Name) -and ((Get-Pct $_.Name) -ne 0) } | ForEach-Object { $_.Name })
    $rest = @($script:Strategies | Sort-Object @{ Expression = { Sort-Key $_.Name } } | Where-Object { (Get-Pct $_.Name) -lt 0 } | ForEach-Object { $_.Name })
    @($r + $fav + $rest | Select-Object -Unique)
}

$script:FixStarted = $false
function Do-AutoFix {
    if ($script:Testing) { return }
    $script:FixStarted = $false
    $cur = $script:LastStrategy
    $next = $null
    if ($cur -and ($script:FixTried -notcontains $cur)) { $next = $cur }
    else { $next = Get-FixCandidates | Where-Object { $script:FixTried -notcontains $_ } | Select-Object -First 1 }
    if (-not $next) {
        if ($script:Alert) { $script:Alert.Fix = 'Автовосстановление не помогло: подходящих стратегий больше нет. Запустите «Подбор» заново.' }
        Render-State; return
    }
    $script:FixTried += $next
    $script:FixStarted = $true
    if ($next -eq $cur) { $msg = "Автовосстановление: перезапускаю «$(Disp $next)»…" } else { $msg = "Автовосстановление: переключаюсь на «$(Disp $next)»…" }
    Log $msg
    if ($script:Alert) { $script:Alert.Fix = $msg }
    $script:Selected = $next
    Start-Strategy $next -Auto
    $script:NextCheck = (Get-Date).AddSeconds(25)
}

function Start-MonCheck {
    if ($script:Mon -or $script:Testing) { return }
    $svcs = @(Get-MonSvcs)
    if ($svcs.Count -eq 0) { return }
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    $c = New-Object System.Net.Http.HttpClient
    $c.Timeout = [TimeSpan]::FromSeconds(6)
    try { $c.DefaultRequestHeaders.UserAgent.ParseAdd('Mozilla/5.0 (Windows NT 10.0; Win64; x64)') } catch { }
    $tasks = @()
    foreach ($s in $svcs) {
        foreach ($u in $s.Urls) { $tasks += @{ Svc = $s.Key; Url = $u; Task = $c.GetAsync($u, [Net.Http.HttpCompletionOption]::ResponseHeadersRead) } }
    }
    $tasks += @{ Svc = '_ctl'; Url = $script:CtlUrl; Task = $c.GetAsync($script:CtlUrl, [Net.Http.HttpCompletionOption]::ResponseHeadersRead) }
    $script:Mon = @{ Client = $c; Tasks = $tasks; Svcs = $svcs; Until = (Get-Date).AddSeconds(8) }
    $script:NextCheck = $null
    $MonText.Text = 'Проверяю связь…'
}

function Finish-MonCheck {
    $m = $script:Mon; $script:Mon = $null
    if ($script:Testing) { try { $m.Client.Dispose() } catch { }; return }
    $now = Get-Date
    $interval = [Math]::Max(1, [Math]::Min(5, [int]$Cfg.MonitorMin))
    $ctl = $m.Tasks | Where-Object { $_.Svc -eq '_ctl' } | Select-Object -First 1
    $ctlOk = $ctl.Task.Status -eq 'RanToCompletion'
    $bad = @(); $total = 0; $totalOk = 0
    foreach ($s in $m.Svcs) {
        $mine = @($m.Tasks | Where-Object { $_.Svc -eq $s.Key })
        $okc = @($mine | Where-Object { $_.Task.Status -eq 'RanToCompletion' }).Count
        $total += $mine.Count; $totalOk += $okc
        if ($okc * 2 -lt $mine.Count) {
            $why = @()
            foreach ($t in $mine) { if ($t.Task.Status -ne 'RanToCompletion') { $why += ([Uri]$t.Url).Host + ': ' + (Get-FailReason $t.Task) } }
            $bad += @{ Name = $s.Name; Why = $why; Ok = $okc; Count = $mine.Count }
        }
    }
    foreach ($t in $m.Tasks) { if ($t.Task.Status -eq 'RanToCompletion') { try { $t.Task.Result.Dispose() } catch { } } }
    try { $m.Client.Dispose() } catch { }

    if (-not $ctlOk -and $totalOk -eq 0) {
        $MonText.Text = ('{0:HH:mm} · нет интернета, проверка пропущена' -f $now)
        $script:NextCheck = $now.AddMinutes(1); return
    }
    if ($bad.Count -eq 0) {
        $MonText.Text = ('Связь проверена в {0:HH:mm} · всё открывается · следующая через {1} мин' -f $now, $interval)
        $wasAlert = [bool]$script:Alert
        $script:MonConfirm = $false
        if ($wasAlert) { Clear-Alert -Recovered }
        $script:NextCheck = $now.AddMinutes($interval); return
    }
    $names = ($bad | ForEach-Object { $_.Name }) -join ', '
    if (-not $script:MonConfirm -and -not $script:Alert) {
        $script:MonConfirm = $true
        $MonText.Text = ('{0:HH:mm} · {1} не отвечает, перепроверяю…' -f $now, $names)
        Log ('Проверка: не отвечает ' + $names + ', перепроверю через 15 сек')
        $script:NextCheck = $now.AddSeconds(15); return
    }
    $lines = @()
    foreach ($b in $bad) {
        $lines += ('{0}: открылось {1} из {2}' -f $b.Name, $b.Ok, $b.Count)
        foreach ($w in ($b.Why | Select-Object -First 3)) { $lines += ('   ' + $w) }
    }
    if ($script:LastStrategy) { $lines += ('Стратегия «{0}» перестала помогать. Перезапустите её или запустите «Подбор».' -f (Disp $script:LastStrategy)) }
    $MonText.Text = ('{0:HH:mm} · сбой: {1}' -f $now, $names)
    Set-Alert ('не открывается ' + $names) $lines
    if ($Cfg.AutoFix) { Do-AutoFix }
    elseif ($Cfg.KeepAlive -and $script:KeepArmed -and $script:LastStrategy -and ($script:FixTried -notcontains $script:LastStrategy)) { Do-AutoFix }
    else { $script:NextCheck = $now.AddMinutes([Math]::Min(1, $interval)) }
}

function Poll-Mon {
    $m = $script:Mon; if (-not $m) { return }
    $done = @($m.Tasks | Where-Object { $_.Task.IsCompleted }).Count
    if ($done -ge $m.Tasks.Count -or (Get-Date) -ge $m.Until) { Finish-MonCheck }
}

$script:KeepStamps = @(); $script:KeepDone = $false; $script:KeepArmed = $false; $script:KeepGoodName = $null
$script:KeepRetryAt = $null; $script:RestartAt = $null; $script:RestartWhy = ''; $script:NetSig = $null; $script:LastTick = $null
$script:LastNetRestart = [datetime]::MinValue; $script:TickN = 0

function Get-NetSig {
    try {
        $r = foreach ($n in [Net.NetworkInformation.NetworkInterface]::GetAllNetworkInterfaces()) {
            if ($n.OperationalStatus -ne 'Up' -or $n.NetworkInterfaceType -eq 'Loopback' -or $n.NetworkInterfaceType -eq 'Tunnel') { continue }
            $ips = @($n.GetIPProperties().UnicastAddresses | Where-Object { $_.Address.AddressFamily -eq 'InterNetwork' } | ForEach-Object { $_.Address.ToString() })
            if ($ips.Count -gt 0) { $n.Id + ':' + ($ips -join ',') }
        }
        return ((@($r) | Sort-Object) -join ';')
    } catch { return '' }
}

# Обход оборвался сам: запускаем заново. После 2-й попытки подряд ещё и сбрасываем драйвер WinDivert.
# Если попыток слишком много, не сдаёмся, а пробуем раз в минуту.
function Try-KeepAlive {
    $script:KeepDone = $false
    if (-not $Cfg.KeepAlive -or -not $script:KeepArmed -or $script:Testing -or $script:Quitting -or -not $script:LastStrategy) { return }
    $now = Get-Date
    $script:KeepStamps = @($script:KeepStamps | Where-Object { ($now - $_).TotalMinutes -lt 10 })
    if ($script:KeepStamps.Count -ge 5) {
        if (-not $script:KeepRetryAt) { Log 'Обход закрывается слишком часто. Не сдаюсь: пробую снова раз в минуту со сбросом WinDivert.' }
        $script:KeepRetryAt = $now.AddSeconds(60)
        return
    }
    # эта стратегия уже получила перезапуски, но не держится: если включено автовосстановление, переходим на другую
    if ($script:KeepStamps.Count -ge 2 -and $Cfg.AutoFix) {
        Log ('«{0}» не держится после перезапусков. Ищу другую рабочую стратегию…' -f (Disp $script:LastStrategy))
        Set-Alert 'обход остановился' @('Процесс winws закрывается сам даже после перезапусков. Пробую другие стратегии.')
        Do-AutoFix
        if ($script:FixStarted) { $script:KeepStamps = @(); $script:MonConfirm = $true; $script:KeepDone = $true; return }
        $script:KeepRetryAt = $now.AddSeconds(60)
        return
    }
    $script:KeepStamps += $now
    if ($script:FixTried -notcontains $script:LastStrategy) { $script:FixTried += $script:LastStrategy }
    if ($script:KeepStamps.Count -ge 2) { Stop-Zapret -Full }
    Log ('Обход оборвался. Запускаю «{0}» снова ({1}/5)…' -f (Disp $script:LastStrategy), $script:KeepStamps.Count)
    $script:KeepDone = $true
    Start-Strategy $script:LastStrategy -Auto
    # если после перезапуска связь не появилась, первая же проверка сразу включит автовосстановление
    $script:MonConfirm = $true
}

# Вызывается раз в секунду из таймера статуса: сон, смена сети, повторные попытки.
function Watch-Resilience {
    $now = Get-Date
    $armed = ($Cfg.KeepAlive -and $script:KeepArmed -and -not $script:Testing -and -not $script:Quitting -and $script:LastStrategy)
    # 1) компьютер проснулся (или интерфейс надолго завис): между тиками пауза, которой не бывает при нормальной работе
    if ($script:LastTick -and ($now - $script:LastTick).TotalSeconds -gt 25) {
        if ($armed -and $script:Running) { $script:RestartAt = $now.AddSeconds(6); $script:RestartWhy = 'компьютер проснулся' }
    }
    $script:LastTick = $now
    # 2) смена сети (Wi-Fi, кабель, VPN): проверяем раз в 5 секунд
    $script:TickN++
    if (($script:TickN % 5) -eq 0) {
        $sig = Get-NetSig
        if ($null -eq $script:NetSig) { $script:NetSig = $sig }
        elseif ($sig -ne $script:NetSig) {
            $script:NetSig = $sig
            if ($armed -and $script:Running -and $sig -and ($now - $script:LastNetRestart).TotalSeconds -gt 30) {
                $script:RestartAt = $now.AddSeconds(5); $script:RestartWhy = 'сеть изменилась'
            }
        }
    }
    # 3) отложенный перезапуск
    if ($script:RestartAt -and $now -ge $script:RestartAt) {
        $script:RestartAt = $null
        if ($armed -and $script:Running) {
            $script:LastNetRestart = $now
            Log ('Обновляю обход ({0}): «{1}»' -f $script:RestartWhy, (Disp $script:LastStrategy))
            Start-Strategy $script:LastStrategy -Auto
        }
    }
    # 4) повторные попытки, если запуск не удался
    if ($script:KeepRetryAt -and $now -ge $script:KeepRetryAt -and -not $script:Running -and -not $script:Starting) {
        $script:KeepRetryAt = $null
        if ($armed -and $script:KeepGoodName -eq $script:LastStrategy) {
            Log ('Повторная попытка запуска «{0}» со сбросом WinDivert…' -f (Disp $script:LastStrategy))
            Stop-Zapret -Full
            $script:KeepRetryAt = (Get-Date).AddSeconds(60)
            $script:FixStarted = $false
            if ($Cfg.AutoFix) { Do-AutoFix }
            if (-not $script:FixStarted) { $script:FixTried = @($script:LastStrategy); Start-Strategy $script:LastStrategy -Auto }
        }
    }
    # 5) долго работает стабильно: обнуляем счётчик аварий
    if ($script:Running -and $script:StartedAt -and ($script:KeepStamps.Count -gt 0 -or ($script:FixTried.Count -gt 0 -and -not $script:Alert)) -and ($now - $script:StartedAt).TotalMinutes -ge 15) { $script:KeepStamps = @(); if (-not $script:Alert) { $script:FixTried = @() } }
}

function Check-Now {
    if (-not $script:Running) { Log 'Обход не запущен: проверять нечего'; return }
    if ($script:Testing) { Log 'Идёт подбор: проверка связи подождёт'; return }
    $script:MonConfirm = $true
    Start-MonCheck
}

# ---------------------------------------------------------------- настройки
function Set-WinStart([bool]$on) {
    try {
        if ($on) {
            $lc = Get-LaunchCmd
            $tr = $lc.Short + ' ' + $lc.Args.Replace('"', '\"')
            $a = "/Create /TN ZapretStudio /TR `"$tr`" /SC ONLOGON /RL HIGHEST /F"
        } else { $a = '/Delete /TN ZapretStudio /F' }
        $pr = Start-Process schtasks.exe -ArgumentList $a -WindowStyle Hidden -Wait -PassThru
        if ($pr.ExitCode -ne 0) { Log 'Не удалось изменить автозапуск Windows' } else { Log ('Автозапуск с Windows: ' + $(if ($on) { 'включён' } else { 'выключен' })) }
    } catch { Log ('Автозапуск: ' + $_.Exception.Message) }
}
function Apply-Topmost { $Win.Topmost = [bool]$Cfg.Topmost; $ChkTop.IsChecked = [bool]$Cfg.Topmost
    if ($Cfg.Topmost) { $BtnPin.SetResourceReference([Windows.Controls.Control]::ForegroundProperty, 'AccentBrush') } else { $BtnPin.SetResourceReference([Windows.Controls.Control]::ForegroundProperty, 'SubBrush') } }

$ChkTray.Add_Click({ $Cfg.TrayOnClose = [bool]$ChkTray.IsChecked; Request-Save })
$ChkAutoLast.Add_Click({ $Cfg.AutoStartLast = [bool]$ChkAutoLast.IsChecked; Request-Save })
$ChkStopExit.Add_Click({ $Cfg.StopOnExit = [bool]$ChkStopExit.IsChecked; Request-Save })
$ChkHide.Add_Click({ $Cfg.HideConsole = [bool]$ChkHide.IsChecked; Request-Save })
$ChkKeep.Add_Click({ $Cfg.KeepAlive = [bool]$ChkKeep.IsChecked; Request-Save })
$ChkTop.Add_Click({ $Cfg.Topmost = [bool]$ChkTop.IsChecked; Apply-Topmost; Request-Save })
$ChkWinStart.Add_Click({ Set-WinStart ([bool]$ChkWinStart.IsChecked) })
$BtnPin.Add_Click({ $Cfg.Topmost = -not [bool]$Cfg.Topmost; Apply-Topmost; Request-Save })
$Win.Add_IsVisibleChanged({ Set-Pulse $script:WantPulse })
$Win.Add_StateChanged({ Set-Pulse $script:WantPulse })

function Reload-Strategies {
    Find-Strategies
    if (-not ($script:Strategies | Where-Object { $_.Name -eq $script:Selected })) { $script:Selected = $null }
    if (-not $script:Selected -and $script:Strategies.Count -gt 0) {
        $last = $script:Strategies | Where-Object { $_.Name -eq $Cfg.Last } | Select-Object -First 1
        if ($last) { $script:Selected = $last.Name } else { $script:Selected = ($script:Strategies | Sort-Object @{ Expression = { Sort-Key $_.Name } } | Select-Object -First 1).Name }
    }
    Rebuild-List; Render-State
    Log ('Найдено стратегий: {0}  ({1})' -f $script:Strategies.Count, $script:WorkDir)
    if ($script:Strategies.Count -eq 0) { Log 'Положите ZapretStudio.ps1 рядом с general*.bat или выберите папку в «Настройках».' }
}
$BtnFolder.Add_Click({
    $d = New-Object System.Windows.Forms.FolderBrowserDialog
    $d.Description = 'Папка с zapret (где лежат general*.bat)'
    if ($d.ShowDialog() -eq 'OK') { $Cfg.StrategyDir = $d.SelectedPath; Request-Save; Reload-Strategies }
})
$BtnRescan.Add_Click({ Reload-Strategies })
$BtnOpen.Add_Click({ Start-Process explorer.exe -ArgumentList "`"$($script:WorkDir)`"" })

