        'Где хранятся настройки|В файле zapret-studio.json рядом с программой. Удалите его, чтобы сбросить всё.',

        '# О ПРОГРАММЕ',
        'Автор|Zapret Studio создана dadramus при помощи KolRau. Авторские права и условия использования: кнопка «О создателях» в верхней части окна и файл LICENSE.txt.'
    )
    $HelpHost.Children.Clear()
    $first = $true
    foreach ($l in $lines) {
        $tb = New-Object System.Windows.Controls.TextBlock
        $tb.TextWrapping = 'Wrap'
        if ($l.StartsWith('# ')) {
            $tb.Text = $l.Substring(2)
            $tb.FontWeight = 'Bold'
            $tb.SetResourceReference([Windows.Controls.TextBlock]::FontSizeProperty, 'Fs11')
            $tb.SetResourceReference([Windows.Controls.TextBlock]::ForegroundProperty, 'SubBrush')
            $top = 18; if ($first) { $top = 0 }
            $tb.Margin = New-Object System.Windows.Thickness 0, $top, 0, 8
            $first = $false
        } else {
            $i = $l.IndexOf('|')
            $r1 = New-Object System.Windows.Documents.Run ($l.Substring(0, $i))
            $r1.FontWeight = 'SemiBold'
            $r2 = New-Object System.Windows.Documents.Run ($l.Substring($i + 1))
            $r2.SetResourceReference([Windows.Documents.TextElement]::ForegroundProperty, 'SubBrush')
            [void]$tb.Inlines.Add($r1)
            [void]$tb.Inlines.Add((New-Object System.Windows.Documents.LineBreak))
            [void]$tb.Inlines.Add($r2)
            $tb.Margin = New-Object System.Windows.Thickness 0, 0, 0, 10
        }
        [void]$HelpHost.Children.Add($tb)
    }
}

