# ---------------------------------------------------------------- трей
$script:Quitting = $false
$script:Tray = New-Object System.Windows.Forms.NotifyIcon
$script:Tray.Text = 'Zapret Studio'
$menu = New-Object System.Windows.Forms.ContextMenuStrip
$miShow = $menu.Items.Add('Показать окно')
$script:TrayToggle = $menu.Items.Add('Запустить последнюю')
$miCheck = $menu.Items.Add('Проверить связь')
$miExit = $menu.Items.Add('Выход')
$script:Tray.ContextMenuStrip = $menu

function Show-Window { $Win.Show(); $Win.WindowState = 'Normal'; [void]$Win.Activate() }
function Exit-App {
    $script:Quitting = $true; $script:KeepArmed = $false
    if ($Cfg.StopOnExit) { Stop-Zapret -Full }
    Save-Settings
    $script:Tray.Visible = $false; $script:Tray.Dispose()
    $app.Shutdown()
}
$miShow.Add_Click({ Show-Window })
$miExit.Add_Click({ Exit-App })
$miCheck.Add_Click({ Check-Now })
$script:TrayToggle.Add_Click({
    if ($script:Running -or $script:Starting) { Stop-ByUser }
    else {
        $n = if ($Cfg.Last) { $Cfg.Last } else { $script:Selected }
        if ($n) { Start-Strategy $n }
    }
})
$script:Tray.Add_DoubleClick({ Show-Window })
$script:BalloonShown = $false
$Win.Add_Closing({ param($sender, $ev)
    if ($script:Quitting) { return }
    if ($Cfg.TrayOnClose) {
        $ev.Cancel = $true; Save-Settings; $Win.Hide()
        if (-not $script:BalloonShown) { $script:BalloonShown = $true; $script:Tray.ShowBalloonTip(2000, 'Zapret Studio', 'Работает в трее. Двойной щелчок — открыть.', [Windows.Forms.ToolTipIcon]::Info) }
    } else { Exit-App }
})

# ---------------------------------------------------------------- таймер статуса
$StatusTimer = New-Object System.Windows.Threading.DispatcherTimer
$StatusTimer.Interval = [TimeSpan]::FromMilliseconds(1000)
$StatusTimer.Add_Tick({
    $procs = [Diagnostics.Process]::GetProcessesByName('winws')
    $run = $procs.Count -gt 0
    foreach ($p in $procs) { $p.Dispose() }
    if ($run -and -not $script:Running) {
        $script:Running = $true
        if (-not $script:StartedAt) { $script:StartedAt = Get-Date }
        if ($script:Starting) { $script:Starting = $false; if (-not $script:Testing) { Log 'Обход активен' } } else { Log 'Обнаружен запущенный winws' }
        $script:KeepRetryAt = $null
        if (-not $script:Testing -and $script:KeepArmed) { $script:KeepGoodName = $script:LastStrategy }
        Render-State
    } elseif (-not $run -and $script:Running) {
        $script:Running = $false; $script:StartedAt = $null; $script:Active = $null; $script:NextCheck = $null
        if (-not $script:Testing) { Log 'winws остановлен' }
        $script:KeepDone = $false
        if (-not $script:Testing -and -not $script:Quitting) { Try-KeepAlive }
        if (-not $script:KeepDone -and $Cfg.Monitor -and -not $script:Testing -and -not $script:Quitting) {
            Set-Alert 'обход остановился' @('Процесс winws завершился сам. Частые причины: антивирус закрыл его, конфликт WinDivert с VPN или другим zapret, либо стратегия вылетела с ошибкой.')
            if ($Cfg.AutoFix) { Do-AutoFix }
        }
        if (-not $script:KeepDone) { Render-State }
    } elseif (-not $run -and $script:Starting -and (Get-Date) -gt $script:StartDeadline) {
        $script:Starting = $false; $script:Active = $null
        Log 'winws не запустился. Проверьте антивирус, права и содержимое папки bin.'
        if ($Cfg.KeepAlive -and $script:KeepArmed -and -not $script:Testing -and -not $script:KeepRetryAt -and $script:KeepGoodName -eq $script:LastStrategy) { $script:KeepRetryAt = (Get-Date).AddSeconds(10) }
        if ($Cfg.AutoFix -and $script:Alert -and $script:KeepArmed -and -not $script:Testing) { Do-AutoFix }
        Render-State
    }
    try { Watch-Resilience } catch { try { Log ('Ошибка наблюдателя: ' + $_.Exception.Message) } catch { } }
    if ($script:Running -and $script:StartedAt) {
        $sp = (Get-Date) - $script:StartedAt
        $UptimeText.Text = 'Работает: {0:00}:{1:00}:{2:00}' -f [int][Math]::Floor($sp.TotalHours), $sp.Minutes, $sp.Seconds
    }
    if ($script:Mon) { Poll-Mon }
    elseif ($Cfg.Monitor -and $script:Running -and -not $script:Testing) {
        if (-not $script:NextCheck) { $script:NextCheck = (Get-Date).AddSeconds(20) }
        elseif ((Get-Date) -ge $script:NextCheck) { Start-MonCheck }
    }
    if ($script:HideUntil -and $Cfg.HideConsole) {
        if ((Get-Date) -gt $script:HideUntil) { $script:HideUntil = $null }
        elseif ([ZNative]::HideWin($script:HideTitle)) { $script:HideUntil = $null }
    }
})

$app.Add_DispatcherUnhandledException({ param($sender, $ev) try { Log ('Ошибка: ' + $ev.Exception.Message) } catch { }; $ev.Handled = $true })

# ---------------------------------------------------------------- старт
$script:Tray.Visible = $true
$ChkTray.IsChecked = [bool]$Cfg.TrayOnClose; $ChkAutoLast.IsChecked = [bool]$Cfg.AutoStartLast
$ChkStopExit.IsChecked = [bool]$Cfg.StopOnExit; $ChkHide.IsChecked = [bool]$Cfg.HideConsole; $ChkPerf.IsChecked = [bool]$Cfg.Perf
if ($Cfg.Sort -eq 'score') { $BtnSort.Content = 'По тесту' }
$ChkKeep.IsChecked = [bool]$Cfg.KeepAlive; $ChkMon.IsChecked = [bool]$Cfg.Monitor; $ChkAutoFix.IsChecked = [bool]$Cfg.AutoFix
$mi = [Math]::Max(1, [Math]::Min(5, [int]$Cfg.MonitorMin)); $SlMonInt.Value = $mi; $LbSlMonInt.Text = ('{0} мин' -f $mi)
Load-Branding; Set-WindowIcons; Update-TrayIcon
$wk = [Windows.SystemParameters]::WorkArea
$Win.MaxWidth = $wk.Width; $Win.MaxHeight = $wk.Height
$Win.Width = [Math]::Min([Math]::Max([double]$Cfg.WinW, 900), $wk.Width); $Win.Height = [Math]::Min([Math]::Max([double]$Cfg.WinH, 620), $wk.Height)
try {
    $q = Start-Process schtasks.exe -ArgumentList '/Query /TN ZapretStudio' -WindowStyle Hidden -Wait -PassThru
    $ChkWinStart.IsChecked = ($q.ExitCode -eq 0)
} catch { }

Pump-Ui
Build-Help
Apply-Font
Apply-Theme -Full
Sync-Look
Sync-Font
Apply-Topmost
Pump-Ui
Reload-Strategies
$pr = [Diagnostics.Process]::GetProcessesByName('winws')
if ($pr.Count -gt 0) { $script:Running = $true; $script:StartedAt = Get-Date; Log 'Обнаружен запущенный winws' }
foreach ($x in $pr) { $x.Dispose() }
$script:Ready = $true
Log 'Zapret Studio готов. Двойной щелчок по карточке — запуск стратегии.'
Render-State
$StatusTimer.Start()

$Win.Add_SourceInitialized({ Apply-Blur })
$Win.Add_Loaded({
    Apply-Blur
    Close-Splash
    try { [void]$Win.Activate() } catch { }
    if ($Cfg.AutoStartLast -and $Cfg.Last -and -not $script:Running) {
        if ($script:Strategies | Where-Object { $_.Name -eq $Cfg.Last }) { Start-Strategy $Cfg.Last }
    }
})

$ErrorActionPreference = 'Continue'
if ($script:Splash) {
    while (((Get-Date) - $script:SplashT0).TotalMilliseconds -lt 2600) { Pump-Ui; Start-Sleep -Milliseconds 25 }
}
[void]$app.Run($Win)
Save-Settings
try { $script:Mutex.ReleaseMutex() } catch { }
}
catch {
    try { if ($script:Splash) { $script:Splash.Close(); $script:Splash = $null } } catch { }
    [void][Windows.MessageBox]::Show(("Zapret Studio не смог запуститься:`n`n" + $_.Exception.Message + "`n`n" + $_.ScriptStackTrace), 'Zapret Studio', 'OK', 'Error')
}
